static void llama_prefill_progress_logf(const char * fmt, ...) {
    va_list args;
    va_start(args, fmt);
    va_list file_args;
    va_copy(file_args, args);

    vfprintf(stderr, fmt, args);
    fflush(stderr);

    const char * path = std::getenv("LLAMA_PREFILL_PROGRESS_LOG");
    if (path && path[0] != '\0') {
        FILE * f = std::fopen(path, "ab");
        if (f) {
            vfprintf(f, fmt, file_args);
            fflush(f);
            std::fclose(f);
        }
    }

    va_end(file_args);
    va_end(args);
}

#ifdef GGML_USE_CUDA
namespace {
class llama_cuda_graph_disable_scope {
public:
    llama_cuda_graph_disable_scope(const std::vector<ggml_backend_ptr> & backends, bool enabled) {
        if (!enabled) {
            return;
        }

        disabled_backends.reserve(backends.size());
        for (const auto & backend : backends) {
            ggml_backend_t raw = backend.get();
            if (raw && ggml_backend_is_cuda(raw)) {
                ggml_backend_cuda_graphs_disable_push(raw);
                disabled_backends.push_back(raw);
            }
        }
    }

    ~llama_cuda_graph_disable_scope() {
        for (auto it = disabled_backends.rbegin(); it != disabled_backends.rend(); ++it) {
            ggml_backend_cuda_graphs_disable_pop(*it);
        }
    }

    llama_cuda_graph_disable_scope(const llama_cuda_graph_disable_scope &) = delete;
    llama_cuda_graph_disable_scope & operator=(const llama_cuda_graph_disable_scope &) = delete;

private:
    std::vector<ggml_backend_t> disabled_backends;
};
} // namespace
#endif

// kv_ram_layer pinned-memory helpers — defined here so cuda_runtime.h is in scope.
void llama_context::kv_ram_layer::alloc_pinned() {
#ifdef GGML_USE_CUDA
    if (k_bytes > 0) { cudaMallocHost((void**)&k_ram, k_bytes); if (k_ram) memset(k_ram, 0, k_bytes); }
    if (v_bytes > 0) { cudaMallocHost((void**)&v_ram, v_bytes); if (v_ram) memset(v_ram, 0, v_bytes); }
    if (k_idx_bytes > 0) { cudaMallocHost((void**)&k_idx_ram, k_idx_bytes); if (k_idx_ram) memset(k_idx_ram, 0, k_idx_bytes); }
#else
    if (k_bytes > 0) { k_ram = (uint8_t*)calloc(k_bytes, 1); }
    if (v_bytes > 0) { v_ram = (uint8_t*)calloc(v_bytes, 1); }
    if (k_idx_bytes > 0) { k_idx_ram = (uint8_t*)calloc(k_idx_bytes, 1); }
#endif
}

void llama_context::kv_ram_layer::free_pinned() {
#ifdef GGML_USE_CUDA
    if (k_ram) { cudaFreeHost(k_ram); k_ram = nullptr; }
    if (v_ram) { cudaFreeHost(v_ram); v_ram = nullptr; }
    if (k_idx_ram) { cudaFreeHost(k_idx_ram); k_idx_ram = nullptr; }
#else
    if (k_ram) { ::free(k_ram); k_ram = nullptr; }
    if (v_ram) { ::free(v_ram); v_ram = nullptr; }
    if (k_idx_ram) { ::free(k_idx_ram); k_idx_ram = nullptr; }
#endif
}

// Pageable bulk storage — plain std::vector, no CUDA pinning.
// k_ram / v_ram are aliased to .data() for use by kv_upload/kv_download
// (which memcpy from these into the pool slot before the H2D transfer).
void llama_context::kv_ram_layer::alloc_pageable() {
    if (k_bytes > 0) {
        pageable_k.assign(k_bytes, 0);
        k_ram = pageable_k.data();
    }
    if (v_bytes > 0) {
        pageable_v.assign(v_bytes, 0);
        v_ram = pageable_v.data();
    }
    if (k_idx_bytes > 0) {
        pageable_k_idx.assign(k_idx_bytes, 0);
        k_idx_ram = pageable_k_idx.data();
    }
}

void llama_context::kv_ram_layer::free_pageable() {
    pageable_k.clear();
    pageable_k.shrink_to_fit();
    pageable_v.clear();
    pageable_v.shrink_to_fit();
    pageable_k_idx.clear();
    pageable_k_idx.shrink_to_fit();
    // k_ram / v_ram were aliases into pageable_k/v — clear without freeing.
    k_ram = nullptr;
    v_ram = nullptr;
    k_idx_ram = nullptr;
}

// Async copyout worker thread: waits for CUDA D2H events, then memcpys pool→pageable.
// This runs the blocking cudaEventSynchronize + memcpy off the main thread so
// kv_download can return immediately after enqueuing.
void llama_context::kv_copyout_thread_fn() {
#ifdef _WIN32
    // Tier mode: the row writes share the NVMe with the DirectStorage weight fetcher that paces the
    // pass; run this thread's I/O at background priority (LLAMA_KV_TIER_BG_IO=0 keeps normal).
    {
        static const bool bg_io = []() {
            const char * e = std::getenv("LLAMA_KV_TIER_BG_IO");
            return !(e && e[0] == '0');
        }();
        if (bg_io && llama_kv_tier::enabled()) {
            SetThreadPriority(GetCurrentThread(), THREAD_MODE_BACKGROUND_BEGIN);
        }
    }
#endif
    while (true) {
        CopyoutJob job;
        {
            std::unique_lock<std::mutex> lk(kv_copyout_mu);
            kv_copyout_cv.wait(lk, [this] {
                return !kv_copyout_queue.empty() || kv_copyout_stop.load(std::memory_order_relaxed);
            });
            if (kv_copyout_queue.empty()) {
                // stop signalled and queue empty — exit
                break;
            }
            job = kv_copyout_queue.front();
            kv_copyout_queue.pop();
        }
        // Wait for GPU D2H to finish on this slot
#ifdef GGML_USE_CUDA
        if (job.done_event) {
            cudaEventSynchronize((cudaEvent_t)job.done_event);
        }
#endif
        // CPU memcpy: pinned pool slot → pageable RAM
        if (job.pageable_k_dst && job.k_bytes > 0) {
            std::memcpy(job.pageable_k_dst, job.pool_src, job.k_bytes);
        }
        if (job.pageable_v_dst && job.v_bytes > 0) {
            std::memcpy(job.pageable_v_dst, job.pool_src + kv_max_k_bytes, job.v_bytes);
        }
        if (job.pageable_k_idx_dst && job.k_idx_bytes > 0) {
            std::memcpy(job.pageable_k_idx_dst, job.pool_src + kv_max_k_bytes + kv_max_v_bytes, job.k_idx_bytes);
        }
        // NVMe tier: write this pass's new rows of layer il once, straight from the pinned slot.
        if (kv_storage_tier && kv_tier && job.tier_n_rows > 0 && job.il >= 0 && !kv_tier->failed()) {
            std::string terr;
            const auto t_w0 = std::chrono::steady_clock::now();
            const uint64_t w_before = kv_tier->bytes_written();
            struct write_timer_end {
                llama_context * c; std::chrono::steady_clock::time_point t0; uint64_t before;
                ~write_timer_end() {
                    c->kv_tier_write_us.fetch_add((uint64_t) std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - t0).count());
                    c->kv_tier_write_bytes.fetch_add(c->kv_tier->bytes_written() - before);
                }
            } write_timer{this, t_w0, w_before};
            if (job.tier_rbk > 0 &&
                !kv_tier->write_rows(job.il, llama_kv_tier::K, job.tier_row0, job.tier_n_rows,
                                     job.pool_src + (size_t) job.tier_row0 * job.tier_rbk, terr)) {
                fprintf(stderr, "*** KV_TIER: write K layer %d rows [%lld,+%lld) FAILED: %s\n",
                        job.il, (long long) job.tier_row0, (long long) job.tier_n_rows, terr.c_str());
                fflush(stderr);
            }
            if (job.tier_rbv > 0 && job.v_bytes > 0 &&
                !kv_tier->write_rows(job.il, llama_kv_tier::V, job.tier_row0, job.tier_n_rows,
                                     job.pool_src + kv_max_k_bytes + (size_t) job.tier_row0 * job.tier_rbv, terr)) {
                fprintf(stderr, "*** KV_TIER: write V layer %d FAILED: %s\n", job.il, terr.c_str());
                fflush(stderr);
            }
            if (job.tier_rbi > 0 && job.k_idx_bytes > 0 &&
                !kv_tier->write_rows(job.il, llama_kv_tier::KIDX, job.tier_row0, job.tier_n_rows,
                                     job.pool_src + kv_max_k_bytes + kv_max_v_bytes + (size_t) job.tier_row0 * job.tier_rbi, terr)) {
                fprintf(stderr, "*** KV_TIER: write k_idx layer %d FAILED: %s\n", job.il, terr.c_str());
                fflush(stderr);
            }
        }
        // Mark slot free so kv_upload can reuse it
        kv_pool_inflight[job.slot_idx].store(0, std::memory_order_release);
        // Decrement pending count and notify any drain waiter in cleanup_kv_ram
        int prev = kv_copyout_pending.fetch_sub(1, std::memory_order_acq_rel);
        if (prev == 1) {
            // We just completed the last pending job — notify drain waiter
            kv_copyout_cv.notify_all();
        }
    }
}

// Out-of-line clear_kv_ram_state — calls free_pinned() / free_pageable()
// which need cuda_runtime.h.
void llama_context::clear_kv_ram_state() {
    if (kv_storage_pageable) {
        // Stop and join copyout worker before freeing pool slots.
        if (kv_copyout_worker.joinable()) {
            {
                std::unique_lock<std::mutex> lk(kv_copyout_mu);
                kv_copyout_stop.store(true, std::memory_order_relaxed);
            }
            kv_copyout_cv.notify_all();
            kv_copyout_worker.join();
        }
        // Destroy per-slot CUDA events
#ifdef GGML_USE_CUDA
        for (auto * ev : kv_pool_dl_events) {
            if (ev) cudaEventDestroy((cudaEvent_t)ev);
        }
#endif
        kv_pool_dl_events.clear();
        kv_pool_inflight.reset();

        // NVMe tier: the worker is joined and the mirror is still here -- the one place every
        // teardown path passes through with both facts true. Verify the files against it.
        kv_tier_verify_mirror("clear_kv_ram_state");

        for (auto & layer : kv_ram_layers) {
            layer.free_pageable();
        }
        // Free pinned pool slots
#ifdef GGML_USE_CUDA
        for (auto * p : kv_pool_bufs) {
            if (p) cudaFreeHost(p);
        }
#else
        for (auto * p : kv_pool_bufs) {
            if (p) ::free(p);
        }
#endif
        kv_pool_bufs.clear();
        kv_pool_n = 0;
        kv_pool_slot_bytes = 0;
        kv_storage_pageable = false;
    } else {
        for (auto & layer : kv_ram_layers) {
            layer.free_pinned();
        }
    }
    kv_ram_layers.clear();
    kv_max_k_bytes = 0;
    kv_max_v_bytes = 0;
    kv_max_k_idx_bytes = 0;
    // NVMe tier: the mirror is gone but the conversation is not. Flush the manifest and keep the
    // store open; the next pass continues it if it starts where the rows end.
    if (kv_tier && kv_tier->is_open()) {
        std::string terr;
        kv_tier->commit(kv_tier->n_tokens(), terr);
        kv_tier_write_tokens_if_any();
        fprintf(stderr, "*** KV_TIER: mirror released; %s holds %lld tokens (%.1f MB written once)\n",
                kv_tier->conv_id().c_str(), (long long) kv_tier->n_tokens(),
                kv_tier->bytes_written() / (1024.0 * 1024.0));
        fflush(stderr);
    }
}

bool llama_context::reserve_prefill_prefix_cells(llama_seq_id seq_id, uint32_t n) {
    llama_memory_i * mem = memory.get();
    if (auto * kv = dynamic_cast<llama_kv_cache *>(mem)) {
        return kv->reserve_prefix_cells(seq_id, n);
    }
    if (auto * iswa = dynamic_cast<llama_kv_cache_iswa *>(mem)) {
        auto * base = const_cast<llama_kv_cache *>(iswa->get_base());
        auto * swa  = const_cast<llama_kv_cache *>(iswa->get_swa());
        const bool a = base ? base->reserve_prefix_cells(seq_id, n) : false;
        const bool b = swa  ? swa->reserve_prefix_cells(seq_id, n)  : false;
        return a && b;
    }
    return false;
}

bool llama_context::kv_tier_enabled() const {
    return llama_kv_tier::enabled();
}

void llama_context::set_kv_tier_prompt_tokens(const std::vector<llama_token> & tokens) {
    kv_tier_prompt_tokens = tokens;
}

uint32_t llama_context::kv_tier_held_rows() const {
    if (!kv_storage_tier || !kv_tier || !kv_tier->is_open()) {
        return 0;
    }
    return (uint32_t) std::max<int64_t>(0, kv_tier->rows(0, llama_kv_tier::K));
}

uint32_t llama_context::kv_decoder_resident_prefix(const llama_token * tokens, size_t n) {
    static const bool delta_enabled = []() {
        const char * e = std::getenv("LLAMA_KV_DELTA_SHIP");
        return !(e && e[0] == '0');
    }();
    if (!delta_enabled || !tokens || n == 0) {
        return 0;
    }
    if (!decode_handoff_executor) {
        refresh_decode_handoff_plan(false);
    }
    if (!decode_handoff_executor || decode_handoff_plan.kv_host.empty() || decode_handoff_plan.kv_port <= 0) {
        return 0;
    }
    static_assert(sizeof(llama_token) == sizeof(int32_t), "token ids are int32 on the wire");
    uint32_t cached = 0;
    std::string status;
    if (!decode_handoff_executor->query_decoder_prefix(reinterpret_cast<const int32_t *>(tokens), n,
                                                       decode_handoff_plan, cached, status)) {
        return 0;
    }
    return cached;
}

bool llama_context::kv_tier_prefix_ready(uint32_t n_past) const {
    return kv_storage_tier && kv_tier && kv_tier->is_open() && n_past > 0 &&
           kv_tier->rows(0, llama_kv_tier::K) >= (int64_t) n_past;
}

void llama_context::kv_tier_write_tokens_if_any() {
    if (!kv_tier || !kv_tier->is_open() || kv_tier_prompt_tokens.empty()) {
        return;
    }
    const size_t n = std::min<size_t>(kv_tier_prompt_tokens.size(), (size_t) std::max<int64_t>(0, kv_tier->n_tokens()));
    std::string err;
    static_assert(sizeof(llama_token) == sizeof(int32_t), "tokens.bin is int32");
    if (!kv_tier->write_tokens((const int32_t *) kv_tier_prompt_tokens.data(), n, err)) {
        fprintf(stderr, "*** KV_TIER: tokens.bin write FAILED: %s\n", err.c_str());
        fflush(stderr);
    }
}

uint32_t llama_context::kv_tier_restore_prefix(const std::vector<llama_token> & req_tokens, uint32_t lcp_min) {
    if (!llama_kv_tier::enabled() || req_tokens.size() <= lcp_min) {
        return 0;
    }
    char fp_hex[32];
    snprintf(fp_hex, sizeof(fp_hex), "%016llx", (unsigned long long) compute_kv_store_model_fp());
    std::string dir;
    int64_t lcp = 0;
    if (!llama_kv_tier::lookup(fp_hex, (const int32_t *) req_tokens.data(), req_tokens.size(), lcp_min, dir, lcp)) {
        return 0;
    }
    if (lcp >= (int64_t) req_tokens.size()) {
        lcp = (int64_t) req_tokens.size() - 1;      // keep one token to prefill: the pass needs a tail
    }
    if (lcp < (int64_t) lcp_min) {
        return 0;
    }
    if (kv_tier && kv_tier->is_open() && kv_tier->path() == dir && kv_tier->rows(0, llama_kv_tier::K) >= lcp) {
        kv_storage_tier = true;
        return (uint32_t) lcp;
    }
    auto tier = std::make_shared<llama_kv_tier>();
    std::string err;
    if (!tier->open_existing(dir, err)) {
        fprintf(stderr, "*** KV_TIER: restore: cannot reopen %s: %s\n", dir.c_str(), err.c_str());
        fflush(stderr);
        return 0;
    }
    const int64_t rows = tier->rows(0, llama_kv_tier::K);
    if (rows < lcp) {
        lcp = rows;
    }
    if (lcp < (int64_t) lcp_min) {
        return 0;
    }
    kv_tier = tier;
    kv_storage_tier = true;
    kv_tier_verify_ok = kv_tier_verify_bad = 0;
    fprintf(stderr, "*** KV_TIER: restore HIT %s reuse=%lld of %zu req tokens (%lld rows on disk); the RTX uploads the prefix from the files and prefills the tail\n",
            tier->conv_id().c_str(), (long long) lcp, req_tokens.size(), (long long) rows);
    fflush(stderr);
    return (uint32_t) lcp;
}

void llama_context::kv_tier_verify_mirror(const char * where) {
    if (!kv_storage_tier || !kv_tier || !kv_tier->is_open() || kv_ram_layers.empty()) {
        return;
    }
    static const bool tier_verify = []() {
        // Off by default since 2026-09-10: four live runs read every file back byte-exact against
        // the mirror; on it doubles the tier's reads per pass (2.3 GB at 11k tokens).
        const char * e = std::getenv("LLAMA_KV_TIER_VERIFY");
        return e && e[0] != 0 && e[0] != '0';
    }();
    if (!tier_verify) {
        return;
    }
    int ok = 0, bad = 0;
    int64_t rows_checked = 0;
    std::vector<uint8_t> scratch;
    for (int il = 0; il < (int) kv_ram_layers.size(); ++il) {
        for (int kk = 0; kk < 3; ++kk) {
            const llama_kv_tier::kind kd = (llama_kv_tier::kind) kk;
            const int64_t nr = kv_tier->rows(il, kd);
            const size_t rb = kv_tier->row_bytes(il, kd);
            const uint8_t * mirror = kd == llama_kv_tier::K ? kv_ram_layers[il].k_ram
                                   : kd == llama_kv_tier::V ? kv_ram_layers[il].v_ram
                                                            : kv_ram_layers[il].k_idx_ram;
            if (nr <= 0 || rb == 0 || !mirror) continue;
            scratch.resize((size_t) nr * rb);
            std::string rerr;
            if (!kv_tier->read_rows(il, kd, 0, nr, scratch.data(), rerr) ||
                std::memcmp(scratch.data(), mirror, scratch.size()) != 0) {
                bad++;
                if (bad <= 4) {
                    // name the first differing row and say which side is zero there
                    int64_t first = -1, n_diff = 0;
                    bool file_zero = false, mirror_zero = false;
                    for (int64_t r = 0; r < nr; ++r) {
                        const uint8_t * a = scratch.data() + (size_t) r * rb;
                        const uint8_t * b = mirror + (size_t) r * rb;
                        if (std::memcmp(a, b, rb) != 0) {
                            if (first < 0) {
                                first = r;
                                file_zero = true; mirror_zero = true;
                                for (size_t i = 0; i < rb; ++i) { if (a[i]) file_zero = false; if (b[i]) mirror_zero = false; }
                            }
                            n_diff++;
                        }
                    }
                    fprintf(stderr, "*** KV_TIER_VERIFY[%s]: MISMATCH layer %d kind %d rows %lld: %lld rows differ, first=%lld (file %s, mirror %s)%s%s\n",
                            where, il, kk, (long long) nr, (long long) n_diff, (long long) first,
                            file_zero ? "zero" : "data", mirror_zero ? "zero" : "data",
                            rerr.empty() ? "" : " read error: ", rerr.c_str());
                }
            } else {
                ok++;
            }
            rows_checked += nr;
        }
    }
    fprintf(stderr, "*** KV_TIER_VERIFY[%s]: files_ok=%d files_bad=%d rows_checked=%lld upload_ok=%d upload_bad=%d written=%.1f MB read=%.1f MB\n",
            where, ok, bad, (long long) rows_checked, kv_tier_verify_ok, kv_tier_verify_bad,
            kv_tier->bytes_written() / (1024.0 * 1024.0), kv_tier->bytes_read() / (1024.0 * 1024.0));
    fflush(stderr);
}

static std::vector<llama_kv_cache *> llama_memory_get_attn_caches_for_export(llama_memory_i * memory) {
    if (!memory) {
        return {};
    }

    if (auto * kv_dsv4 = dynamic_cast<llama_kv_cache_dsv4 *>(memory)) {
        memory = kv_dsv4->get_raw();
    }

    if (auto * kv = dynamic_cast<llama_kv_cache *>(memory)) {
        return { kv };
    }

    if (auto * kv_iswa = dynamic_cast<llama_kv_cache_iswa *>(memory)) {
        std::vector<llama_kv_cache *> caches;
        if (auto * base = kv_iswa->get_base()) {
            caches.push_back(base);
        }
        if (auto * swa = kv_iswa->get_swa()) {
            caches.push_back(swa);
        }
        return caches;
    }

    if (auto * hybrid = dynamic_cast<llama_memory_hybrid *>(memory)) {
        if (auto * attn = hybrid->get_mem_attn()) {
            return { attn };
        }
        return {};
    }

    if (auto * hybrid_iswa = dynamic_cast<llama_memory_hybrid_iswa *>(memory)) {
        std::vector<llama_kv_cache *> caches;
        if (auto * attn = hybrid_iswa->get_mem_attn()) {
            if (auto * base = attn->get_base()) {
                caches.push_back(base);
            }
            if (auto * swa = attn->get_swa()) {
                caches.push_back(swa);
            }
        }
        return caches;
    }

    return {};
}

static std::string llama_prefill_tail_tokens_sidecar_path(const std::string & artifact_path) {
    return artifact_path + ".tail.bin";
}

static bool llama_write_tail_tokens_sidecar(
        const std::string & path,
        const std::vector<llama_token> & tokens,
        std::string & err) {
    FILE * f = fopen(path.c_str(), "wb");
    if (!f) {
        err = "failed to open tail token sidecar " + path;
        return false;
    }

    const size_t written = tokens.empty()
        ? 0
        : fwrite(tokens.data(), sizeof(llama_token), tokens.size(), f);
    fclose(f);

    if (written != tokens.size()) {
        err = format("failed to write tail token sidecar %s (%zu/%zu tokens)",
                     path.c_str(), written, tokens.size());
        return false;
    }

    return true;
}

static std::string llama_detokenize_prompt_payload(
        const llama_vocab *              vocab,
        const std::vector<llama_token> & tokens);

