// STEP 2 (2026-06-01): path-independent per-layer dump to confirm the SM120 F16-VKQ diagnosis.
// Installed via cparams.cb_eval so it fires on BOTH the RTX streaming layer-major path AND the
// Mac receiver's full-local re-prefill (same llama lib). With ship-embeddings the receiver
// re-prefills the SAME shipped RTX embeddings, so diffing the RTX (NCOLS=32 F16 VKQ) vs the Mac
// (Metal F32) __fattn__ output isolates the FA output-accumulation precision — no clip/weight skew.
// Gated by LLAMA_LAYER_CMP_DUMP=1; SIDE label by LLAMA_LAYER_CMP_SIDE (rtx|mac); output dir by
// LLAMA_LAYER_CMP_DIR; layer filter by LLAMA_LAYER_CMP_LAYERS (csv, default 0,1,2,30,60).
static bool llama_layer_cmp_eval_cb(ggml_tensor * t, bool ask, void * /*user_data*/) {
    static const std::string side = []() { const char * e = std::getenv("LLAMA_LAYER_CMP_SIDE"); return std::string(e && e[0] ? e : "x"); }();
    static const std::string dir  = []() { const char * e = std::getenv("LLAMA_LAYER_CMP_DIR");  return std::string(e && e[0] ? e : "."); }();
    static const std::vector<int> layers = []() {
        std::vector<int> v;
        const char * e = std::getenv("LLAMA_LAYER_CMP_LAYERS");
        if (e && e[0]) {
            std::string s(e); size_t p = 0;
            while (p <= s.size()) {
                size_t c = s.find(',', p);
                std::string tok = s.substr(p, c == std::string::npos ? std::string::npos : c - p);
                if (!tok.empty()) v.push_back(atoi(tok.c_str()));
                if (c == std::string::npos) break;
                p = c + 1;
            }
        } else { v = {0, 1, 2, 30, 60}; }
        return v;
    }();
    const char * nm = t ? ggml_get_name(t) : nullptr;
    if (!nm) return false;
    int il = -1; const char * kind = nullptr;
    if      (strncmp(nm, "__fattn__-", 10) == 0) { il = atoi(nm + 10); kind = "fattn"; }
    else if (strncmp(nm, "l_out-",      6) == 0) { il = atoi(nm + 6);  kind = "lout";  }
    // [DIAG_SPARSE_NAN 2026-06-25] probe the DSA-on multi-ubatch sparse attention internals
    // (post-softmax kq, kqv, kqv_mla) to localize the first-NaN op. Named in build_attn_mha
    // when LLAMA_DIAG_SPARSE_NAN is set. Zero cost otherwise (these names never appear).
    else if (strncmp(nm, "diagsoftmax-", 12) == 0) { il = atoi(nm + 12); kind = "diagsoftmax"; }
    else if (strncmp(nm, "diagkqvmla-",  11) == 0) { il = atoi(nm + 11); kind = "diagkqvmla"; }
    else if (strncmp(nm, "diagkqv-",      8) == 0) { il = atoi(nm + 8);  kind = "diagkqv";  }
    else if (strncmp(nm, "diagmask-",     9) == 0) { il = atoi(nm + 9);  kind = "diagmask"; }
    else if (strncmp(nm, "diagtopk-",     9) == 0) { il = atoi(nm + 9);  kind = "diagtopk"; }
    else if (strncmp(nm, "diagscore-",   10) == 0) { il = atoi(nm + 10); kind = "diagscore"; }
    else return false;
    bool want = false;
    for (int L : layers) { if (L == il) { want = true; break; } }
    if (!want) return false;
    if (ask) return true;  // observe -> force materialization; ask=false then reads it
    if (!t->data) return true;
    const size_t nbytes = ggml_nbytes(t);
    std::vector<uint8_t> buf(nbytes);
    ggml_backend_tensor_get(t, buf.data(), 0, nbytes);  // synchronous device->host copy
    // [DIAG_SPARSE_NAN 2026-06-25] for the diag* kinds, only dump the ubatch that actually
    // contains NaN (multiple ubatches share the same shape -> filename collides; the NaN one
    // is the interesting/corrupt ubatch). Append _NAN<count> so it never collides with clean ones.
    const bool is_diag = (strncmp(kind, "diag", 4) == 0);
    static long long diag_seq = 0;
    long long nan_count = 0;
    long long this_seq = -1;
    if (is_diag) {
        if (t->type == GGML_TYPE_F32 && strcmp(kind, "diagscore") != 0) {
            const float * fp = (const float *) buf.data();
            const size_t n = nbytes / sizeof(float);
            for (size_t i = 0; i < n; i++) { if (fp[i] != fp[i]) nan_count++; }
            if (nan_count == 0) return true;  // skip clean ubatches; we only want the corrupt one
        } else {
            // mask (F16) / topk (I32): can't NaN-detect; tag each call with a seq so ubatches don't collide.
            this_seq = diag_seq++;
        }
    }
    // Key the filename by tensor shape (ne1 x ne2) so chunks of different sizes (the RTX single
    // prefill vs the receiver's separate prefix/image/suffix decodes) do not overwrite each other.
    // The Python diff matches the image region by token count (361 image cells / 385 full).
    char path[1024];
    if (is_diag && this_seq >= 0) {
        snprintf(path, sizeof(path), "%s/cmp_%s_%s_L%d_%lldx%lldx%lld_seq%lld.bin", dir.c_str(), side.c_str(), kind, il,
                 (long long) t->ne[1], (long long) t->ne[2], (long long) t->ne[3], this_seq);
    } else if (is_diag) {
        snprintf(path, sizeof(path), "%s/cmp_%s_%s_L%d_%lldx%lldx%lld_NAN%lld.bin", dir.c_str(), side.c_str(), kind, il,
                 (long long) t->ne[1], (long long) t->ne[2], (long long) t->ne[3], nan_count);
    } else
    snprintf(path, sizeof(path), "%s/cmp_%s_%s_L%d_%lldx%lldx%lld.bin", dir.c_str(), side.c_str(), kind, il,
             (long long) t->ne[1], (long long) t->ne[2], (long long) t->ne[3]);
    FILE * f = fopen(path, "wb");
    if (f) {
        int32_t hdr[6] = { (int32_t) t->type, (int32_t) t->ne[0], (int32_t) t->ne[1],
                           (int32_t) t->ne[2], (int32_t) t->ne[3], il };
        fwrite(hdr, sizeof(hdr), 1, f);
        fwrite(buf.data(), 1, nbytes, f);
        fclose(f);
        fprintf(stderr, "*** LAYER_CMP[%s] wrote %s ne=[%lld,%lld,%lld] type=%d %zuB\n",
                side.c_str(), path, (long long) t->ne[0], (long long) t->ne[1],
                (long long) t->ne[2], (int) t->type, nbytes);
        fflush(stderr);
    }
    return true;
}

// RESIDENT_LID_TRACE marker.  This callback is installed only when
// LLAMA_DSV4_LID_TOPK_TRACE names an output file.  It preserves any caller
// callback and observes lid_score_masked plus lid_top_k only while a one-token
// resident decode is explicitly armed in decode().
bool llama_context::resident_lid_eval_callback(ggml_tensor * t, bool ask, void * user_data) {
    auto * ctx = static_cast<llama_context *>(user_data);
    const bool user_observe = ctx->resident_lid_trace_user_cb
            ? ctx->resident_lid_trace_user_cb(t, ask, ctx->resident_lid_trace_user_data)
            : false;

    const char * name = t ? ggml_get_name(t) : nullptr;
    const bool is_lid_score = ctx->resident_lid_trace_armed && name &&
            std::strncmp(name, "lid_score_masked-", 17) == 0;
    const bool is_lid_topk = ctx->resident_lid_trace_armed && name &&
            std::strncmp(name, "lid_top_k-", 10) == 0;
    const bool is_lid_k = ctx->resident_lid_trace_armed && name &&
            std::strncmp(name, "lid_k-", 6) == 0;
    const bool is_lid_q = ctx->resident_lid_trace_armed && name &&
            std::strncmp(name, "lid_q_rot-", 10) == 0;
    // Decode attention tensors, captured HERE rather than by reading res->get_gf() after decode()
    // returns. That post-hoc pattern does not survive this route (stream_local + RETAIN_SLOT_KV +
    // route-reuse + the layer-major executor): by the time it reads, the scheduler has reused or
    // freed the buffers, and it dumps plausible-looking garbage -- a "mask" of small negative floats,
    // an output of all-NaN. Three attempts to shore it up (unique names, forward-expand, pinning the
    // pre-cast tensor) all still produced at least one provably-wrong tensor, which invalidates the
    // whole set. cb_eval sees each tensor the moment its node computes and is demonstrably reliable
    // on this exact route -- it is what produces the sane LID scores below.
    const bool is_csa_dec = ctx->resident_lid_trace_armed && name &&
            std::strncmp(name, "csa_dec_", 8) == 0;

    // CONTROL. csa_dec_out came back 100% NaN at every layer and step while the model kept emitting
    // fluent text -- impossible for the same forward pass, so the question is not "why NaN" but
    // "which graph am I even looking at". result_norm / result_output are the final norm and the
    // logits: sampling demonstrably works, so they MUST be finite in the graph that produces tokens.
    // If they capture as NaN too, this callback is attached to a graph that is built but not the one
    // generating output, and every decode reading taken through it is meaningless.
    const bool is_control = ctx->resident_lid_trace_armed && name &&
            (std::strcmp(name, "result_output") == 0 || std::strcmp(name, "result_norm") == 0);

    if (ask) {
        return user_observe || is_lid_score || is_lid_topk || is_lid_k || is_lid_q || is_csa_dec || is_control;
    }

    if (is_csa_dec || is_control) {
        try {
            static std::mutex                  dec_mutex;
            static std::map<std::string, int>  dec_counts;
            std::lock_guard<std::mutex> lock(dec_mutex);
            int & seen = dec_counts[name];
            // LAST firing wins, not the first three. Capping at the first N captures the WARM-UP /
            // reserve evaluations, whose inputs are garbage -- which is why the control capture of
            // result_output came back 100% NaN even after synchronising every backend, while the
            // model was demonstrably sampling coherent text from finite logits. Overwrite one file
            // per tensor on every firing so the surviving copy is the most recent real decode step.
            if (!ctx->resident_lid_trace_path.empty()) {
                // Synchronise EVERY backend, not just the one this tensor is assigned to. This fork
                // deliberately skips the scheduler's per-boundary sync when eval callbacks are armed
                // (skip_eval_sync + CUDA events, see AGENTS.md), so when the callback fires the
                // kernel may still be in flight -- and if get_tensor_backend returns null there is no
                // sync at all and the readback returns uninitialised memory. That is exactly what was
                // observed: the CONTROL capture of result_output (the logits) came back 100% NaN
                // while sampling was demonstrably producing coherent text, which is impossible unless
                // the read, not the compute, was wrong.
                if (ctx->sched) {
                    if (ggml_backend_t bk = ggml_backend_sched_get_tensor_backend(ctx->sched.get(), t)) {
                        ggml_backend_synchronize(bk);
                    }
                    const int nb_sched = ggml_backend_sched_get_n_backends(ctx->sched.get());
                    for (int bi = 0; bi < nb_sched; ++bi) {
                        if (ggml_backend_t bk = ggml_backend_sched_get_backend(ctx->sched.get(), bi)) {
                            ggml_backend_synchronize(bk);
                        }
                    }
                }
                const size_t nbytes = ggml_nbytes(t);
                std::vector<uint8_t> raw(nbytes);
                ggml_backend_tensor_get(t, raw.data(), 0, nbytes);
                char fname[1024];
                snprintf(fname, sizeof(fname), "%s.eval.%s.last.bin",
                         ctx->resident_lid_trace_path.c_str(), name);
                if (FILE * fb = std::fopen(fname, "wb")) {
                    fwrite(raw.data(), 1, nbytes, fb);
                    std::fclose(fb);
                }
                char mname[1024];
                snprintf(mname, sizeof(mname), "%s.evalmanifest.tsv",
                         ctx->resident_lid_trace_path.c_str());
                if (FILE * fm = std::fopen(mname, "ab+")) {
                    fprintf(fm, "%s\t%d\t%s\t%lld\t%lld\t%lld\t%zu\n", name, seen,
                            ggml_type_name(t->type), (long long) t->ne[0], (long long) t->ne[1],
                            (long long) t->ne[2], nbytes);
                    std::fclose(fm);
                }
                seen++;
            }
        } catch (...) {}
        // FAIL-OPEN, same reason as the lid_k/lid_q branch: returning false breaks the sched graph
        // loop, so the later lid_top_k node that writes the trace would never fire.
        return true;
    }

    if (is_lid_k || is_lid_q) {
        // Distinguish query-vs-key for bug#2: capture the decode-token QUERY norm (lid_q_rot, a computed node)
        // and the needle-row KEY norm vs a reference row (700) (lid_k). F16/F32-aware. Additive, env-gated only.
        try {
            const bool f16 = (t->type == GGML_TYPE_F16);
            const bool f32 = (t->type == GGML_TYPE_F32);
            if ((f16 || f32) && t->ne[0] > 0) {
                ggml_backend_t backend = ctx->sched
                        ? ggml_backend_sched_get_tensor_backend(ctx->sched.get(), t) : nullptr;
                if (backend) { ggml_backend_synchronize(backend); }
                const size_t nf = (size_t) t->ne[0];
                auto norm_at = [&](size_t byte_off, int32_t & nan_out) -> float {
                    std::vector<uint8_t> raw(nf * (f16 ? 2u : 4u));
                    ggml_backend_tensor_get(t, raw.data(), byte_off, raw.size());
                    double ss = 0.0; int nan = 0;
                    for (size_t i = 0; i < nf; ++i) {
                        const float v = f16 ? ggml_fp16_to_fp32(((const ggml_fp16_t *) raw.data())[i])
                                            : ((const float *) raw.data())[i];
                        if (std::isnan(v) || std::isinf(v)) { nan++; } else { ss += (double) v * v; }
                    }
                    nan_out = nan;
                    return (float) std::sqrt(ss / (double) nf);
                };
                if (is_lid_q) {
                    int32_t qn = 0;
                    ctx->resident_lid_trace_query_norm = norm_at(0, qn);  // decode-token query, first head
                    ctx->resident_lid_trace_query_nan  = qn;
                } else {  // is_lid_k
                    const int32_t nrow = ctx->resident_lid_trace_needle_row;
                    const int32_t refrow = 700;
                    if (nrow >= 0 && nrow < t->ne[2] && refrow < t->ne[2]) {
                        int32_t nn = 0, rn = 0;
                        ctx->resident_lid_trace_needle_key_norm = norm_at((size_t) nrow   * t->nb[2], nn);
                        ctx->resident_lid_trace_needle_key_nan  = nn;
                        ctx->resident_lid_trace_ref_key_norm    = norm_at((size_t) refrow * t->nb[2], rn);
                        ctx->resident_lid_trace_key_il          = std::atoi(name + 6);
                    }
                }
            }
        } catch (...) {}
        return true;  // FAIL-OPEN: returning false (user_observe) here BREAKS the sched graph loop (cf a39da797)
                      // -> the later lid_top_k node (which writes the trace) never fires. Must return true.
    }

    if (is_lid_score) {
        // Read the first (current resident-decode) token/stream score column
        // immediately after the masked-score node.  This synchronization and
        // readback exist only while LLAMA_DSV4_LID_TOPK_TRACE is armed.  Score
        // capture is purely additive: any failure leaves the score fields at
        // their defaults and must not prevent the later lid_top_k callback.
        ctx->resident_lid_trace_score_il = -1;
        ctx->resident_lid_trace_scores.clear();
        try {
            if (t->type != GGML_TYPE_F32 || t->ne[0] <= 0) {
                return true;
            }
            const size_t n_lid = (size_t) t->ne[0];
            const bool span_fits = t->nb[0] >= sizeof(float) &&
                    n_lid - 1 <= (SIZE_MAX - sizeof(float)) / t->nb[0];
            const size_t span = span_fits ? (n_lid - 1) * t->nb[0] + sizeof(float) : 0;
            if (span_fits && span <= ggml_nbytes(t)) {
                ggml_backend_t backend = ctx->sched
                        ? ggml_backend_sched_get_tensor_backend(ctx->sched.get(), t)
                        : nullptr;
                if (backend) {
                    ggml_backend_synchronize(backend);
                }

                std::vector<uint8_t> raw(span);
                ggml_backend_tensor_get(t, raw.data(), 0, span);
                std::vector<float> scores(n_lid);
                for (size_t i = 0; i < n_lid; ++i) {
                    std::memcpy(&scores[i], raw.data() + i * t->nb[0], sizeof(float));
                }
                ctx->resident_lid_trace_scores = std::move(scores);
                ctx->resident_lid_trace_score_il = std::atoi(name + 17);
            }
        } catch (...) {
            ctx->resident_lid_trace_score_il = -1;
            ctx->resident_lid_trace_scores.clear();
        }

        // A false post-observation return cancels the rest of scheduler graph
        // evaluation.  This node is observed for tracing, so always continue to
        // the lid_top_k node even when score capture was unavailable.
        return true;
    }
    if (!is_lid_topk || t->type != GGML_TYPE_I32 || t->ne[0] <= 0) {
        return user_observe;
    }

    // The callback runs immediately after this TOP_K result.  Pay an explicit
    // backend sync only under the trace gate so the selected row IDs and the
    // visibility scalar are stable for readback.
    ggml_backend_t backend = ctx->sched
            ? ggml_backend_sched_get_tensor_backend(ctx->sched.get(), t)
            : nullptr;
    if (backend) {
        ggml_backend_synchronize(backend);
    }

    ggml_tensor * topk_op = t;
    while (topk_op && topk_op->op != GGML_OP_TOP_K) {
        topk_op = topk_op->src[0];
    }
    const int64_t n_lid = topk_op && topk_op->src[0] ? topk_op->src[0]->ne[0] : 0;

    int32_t n_visible = -1;
    if (auto * res = ctx->get_graph_result()) {
        if (ggml_tensor * visible = ggml_graph_get_tensor(res->get_gf(), "dsv4_lid_n_visible")) {
            if (visible->type == GGML_TYPE_I32 && ggml_nelements(visible) > 0) {
                ggml_backend_tensor_get(visible, &n_visible, 0, sizeof(n_visible));
            }
        }
    }

    const size_t k = (size_t) t->ne[0];
    const size_t span = (k - 1) * t->nb[0] + sizeof(int32_t);
    std::vector<uint8_t> raw(span);
    ggml_backend_tensor_get(t, raw.data(), 0, span);
    std::vector<int32_t> rows(k);
    bool needle_selected = false;
    for (size_t i = 0; i < k; ++i) {
        std::memcpy(&rows[i], raw.data() + i * t->nb[0], sizeof(rows[i]));
        needle_selected |= rows[i] == ctx->resident_lid_trace_needle_row;
    }

    const int il = std::atoi(name + 10);
    float needle_score = std::numeric_limits<float>::quiet_NaN();
    int64_t needle_rank = -1;
    float top1_score = std::numeric_limits<float>::quiet_NaN();
    float kth_score = std::numeric_limits<float>::quiet_NaN();
    try {
        if (ctx->resident_lid_trace_score_il == il && !ctx->resident_lid_trace_scores.empty()) {
            const auto & scores = ctx->resident_lid_trace_scores;
            const int32_t needle_row = ctx->resident_lid_trace_needle_row;
            if (needle_row >= 0 && (size_t) needle_row < scores.size()) {
                needle_score = scores[(size_t) needle_row];
                needle_rank = 0;
                for (float score : scores) {
                    // Masked rows are -INFINITY.  In particular, do not count
                    // another masked row as greater when the needle is masked.
                    if (!(std::isinf(score) && score < 0.0f) && score > needle_score) {
                        ++needle_rank;
                    }
                }
            }

            std::vector<float> ordered_scores;
            ordered_scores.reserve(scores.size());
            for (float score : scores) {
                if (!std::isnan(score)) {
                    ordered_scores.push_back(score);
                }
            }
            if (!ordered_scores.empty()) {
                top1_score = *std::max_element(ordered_scores.begin(), ordered_scores.end());
                if (ordered_scores.size() >= k) {
                    std::nth_element(ordered_scores.begin(), ordered_scores.begin() + (k - 1),
                            ordered_scores.end(), std::greater<float>());
                    kth_score = ordered_scores[k - 1];
                }
            }
        }
    } catch (...) {
        needle_score = std::numeric_limits<float>::quiet_NaN();
        needle_rank = -1;
        top1_score = std::numeric_limits<float>::quiet_NaN();
        kth_score = std::numeric_limits<float>::quiet_NaN();
    }

    static std::mutex trace_mutex;
    std::lock_guard<std::mutex> lock(trace_mutex);
    FILE * fp = std::fopen(ctx->resident_lid_trace_path.c_str(), "ab+");
    if (!fp) {
        LLAMA_LOG_ERROR("%s: failed to open resident DSV4 LID trace '%s'\n",
                __func__, ctx->resident_lid_trace_path.c_str());
        return user_observe;
    }
    if (std::fseek(fp, 0, SEEK_END) == 0 && std::ftell(fp) == 0) {
        std::fprintf(fp, "# LLAMA_DSV4_RESIDENT_LID_TRACE v1\n");
        std::fprintf(fp, "step\tpos\til\tn_visible\tn_lid\tK\tneedle_row\tneedle_in_scored_range\tneedle_selected\tselected_rows\tneedle_score\tneedle_rank\ttop1_score\tkth_score\tneedle_key_norm\tref_key_norm\tneedle_key_nan\tquery_norm\tquery_nan\n");
    }
    const bool needle_visible = ctx->resident_lid_trace_needle_row >= 0 &&
            ctx->resident_lid_trace_needle_row < n_visible;
    std::fprintf(fp, "%llu\t%d\t%d\t%d\t%lld\t%zu\t%d\t%d\t%d\t",
            (unsigned long long) ctx->resident_lid_trace_cur_step,
            (int) ctx->resident_lid_trace_pos, il, n_visible, (long long) n_lid, k,
            ctx->resident_lid_trace_needle_row, needle_visible ? 1 : 0, needle_selected ? 1 : 0);
    for (size_t i = 0; i < rows.size(); ++i) {
        if (i != 0) {
            std::fputc(',', fp);
        }
        std::fprintf(fp, "%d", rows[i]);
    }
    std::fprintf(fp, "\t%.9g\t%lld\t%.9g\t%.9g\t%.6g\t%.6g\t%d\t%.6g\t%d\n",
            needle_score, (long long) needle_rank, top1_score, kth_score,
            ctx->resident_lid_trace_needle_key_norm, ctx->resident_lid_trace_ref_key_norm,
            ctx->resident_lid_trace_needle_key_nan,
            ctx->resident_lid_trace_query_norm, ctx->resident_lid_trace_query_nan);
    std::fclose(fp);
    return user_observe;
}

static uint64_t llama_dsv4_fingerprint_bytes(const uint8_t * data, size_t size) {
    uint64_t hash = 1469598103934665603ULL;
    for (size_t i = 0; i < size; ++i) {
        hash ^= data[i];
        hash *= 1099511628211ULL;
    }
    return hash;
}

// MIGRATE_FINGERPRINT marker.  Hash full raw compressed K rows using the same
// (stream * kv_size + row) * row_size addressing contract as DSV4 state I/O.
static void llama_dsv4_migrate_fingerprint_append(
        const char * path, const char * phase, const llama_kv_cache_dsv4 * dsv4) {
    if (!path || !path[0] || !dsv4) {
        return;
    }

    struct cache_desc {
        const char * name;
        const llama_kv_cache * kv;
    };
    const cache_desc caches[] = {
        { "lid", dsv4->get_lid() },
        { "csa", dsv4->get_csa() },
    };
    // LLAMA_DSV4_FINGERPRINT_ROWS="a-b,c,d-e" overrides the sampled row set (dense scans of the
    // written range when localizing which rows diverge between runs).
    static const std::vector<uint32_t> sample_rows = []() {
        std::vector<uint32_t> v;
        const char * e = std::getenv("LLAMA_DSV4_FINGERPRINT_ROWS");
        if (e && e[0]) {
            const char * p = e;
            while (*p) {
                char * end = nullptr;
                const long a = std::strtol(p, &end, 10);
                if (end == p) break;
                p = end;
                long b = a;
                if (*p == '-') { b = std::strtol(p + 1, &end, 10); p = end; }
                for (long r = a; r <= b && r - a < 100000; ++r) v.push_back((uint32_t) r);
                if (*p == ',') ++p;
            }
        }
        if (v.empty()) v = { 0, 700, 1400, 1425, 2000, 2675 };
        return v;
    }();
    static std::mutex trace_mutex;
    std::lock_guard<std::mutex> lock(trace_mutex);

    FILE * fp = std::fopen(path, "ab+");
    if (!fp) {
        LLAMA_LOG_ERROR("%s: failed to open DSV4 migration fingerprint '%s'\n", __func__, path);
        return;
    }
    if (std::fseek(fp, 0, SEEK_END) == 0 && std::ftell(fp) == 0) {
        std::fprintf(fp, "# LLAMA_DSV4_MIGRATE_FINGERPRINT v1\n");
        std::fprintf(fp, "phase\tcache\til\tstream\trow\tfingerprint\tstream_offset\trow_size\n");
    }

    for (const auto & cache : caches) {
        if (!cache.kv) {
            continue;
        }
        const uint32_t kv_size = cache.kv->get_size();
        const uint32_t n_stream = cache.kv->get_n_stream();
        for (uint32_t il : cache.kv->get_layer_ids()) {
            ggml_tensor * tensor = cache.kv->get_k_storage((int32_t) il);
            if (!tensor) {
                continue;
            }
            const size_t row_size = ggml_row_size(tensor->type, tensor->ne[0]);
            std::vector<uint8_t> bytes(row_size);
            for (uint32_t stream = 0; stream < n_stream; ++stream) {
                const size_t stream_offset = (size_t) stream * kv_size * row_size;
                // LLAMA_DSV4_FINGERPRINT_DUMPROWS="a,b": additionally emit the FULL raw bytes
                // (hex) of those rows — the round-5 numeric-recompute oracle needs the actual
                // cache row contents, not just hashes.
                static const std::vector<uint32_t> dump_rows = []() {
                    std::vector<uint32_t> v;
                    const char * e = std::getenv("LLAMA_DSV4_FINGERPRINT_DUMPROWS");
                    if (e && e[0]) {
                        const char * p = e;
                        while (*p) {
                            char * end = nullptr;
                            const long a = std::strtol(p, &end, 10);
                            if (end == p) break;
                            p = end;
                            long b = a;
                            if (*p == '-') { b = std::strtol(p + 1, &end, 10); p = end; }
                            for (long rr = a; rr <= b && rr - a < 100000; ++rr) v.push_back((uint32_t) rr);
                            if (*p == ',') ++p;
                        }
                    }
                    return v;
                }();
                for (uint32_t row : sample_rows) {
                    if (row >= kv_size) {
                        continue;
                    }
                    const size_t offset = stream_offset + (size_t) row * row_size;
                    ggml_backend_tensor_get(tensor, bytes.data(), offset, row_size);
                    const uint64_t hash = llama_dsv4_fingerprint_bytes(bytes.data(), bytes.size());
                    const bool dump_this = std::find(dump_rows.begin(), dump_rows.end(), row) != dump_rows.end();
                    std::fprintf(fp, "%s\t%s\t%u\t%u\t%u\t%016llx\t%zu\t%zu",
                            phase, cache.name, il, stream, row,
                            (unsigned long long) hash, stream_offset, row_size);
                    if (dump_this) {
                        std::fprintf(fp, "\t");
                        for (size_t b = 0; b < row_size; ++b) {
                            std::fprintf(fp, "%02x", bytes[b]);
                        }
                    }
                    std::fprintf(fp, "\n");
                }
            }
        }
    }
    std::fclose(fp);
}

// LLAMA_DSV4_LID_PROBE post-decode readback for the ordinary/resident decode path (the
// streaming executor has its own hook in llama-prefill-stream.cpp). Reads the pinned
// lid_score_masked-<il> / lid_top_k-<il> outputs after graph compute and appends the same
// v2 TSV columns (sel_consist, kth/needle/top1 scores, needle rank). Env-gated, zero cost
// when off. Requires the ggml_set_output pinning in build_lid_top_k (deepseek-v4.cpp).
static void llama_dsv4_lid_probe_dump(
        const char * path, ggml_cgraph * gf, ggml_backend_sched_t sched,
        int64_t pos, int n_layer) {
    if (!path || !path[0] || !gf) {
        return;
    }
    static const int32_t needle_row = []() {
        const char * e = std::getenv("LLAMA_DSV4_LID_NEEDLE_ROW");
        return e && e[0] != '\0' ? std::atoi(e) : -1;
    }();
    static std::mutex      probe_mutex;
    static std::atomic_int probe_step { 0 };
    std::lock_guard<std::mutex> lock(probe_mutex);

    FILE * fp = std::fopen(path, "ab+");
    if (!fp) {
        return;
    }
    if (std::fseek(fp, 0, SEEK_END) == 0 && std::ftell(fp) == 0) {
        std::fprintf(fp, "# LLAMA_DSV4_LID_TOPK_TRACE v2 (LID_PROBE columns appended when scores captured)\n");
        std::fprintf(fp, "step\tpos\tlayer\tn_lid\tn_visible\tK\tselected_impl\tselected_rows"
                         "\tsel_consist\tkth_score\tneedle_score\tneedle_rank\ttop1_score\tn_finite\n");
    }
    const int step = probe_step.fetch_add(1, std::memory_order_relaxed);

    // round-6: dump the pinned decode QUERY tensors (layer 2, first 3 steps) as raw
    // binaries next to the TSV — inputs for the offline score cross-check.
    static std::atomic_int q_dump_count { 0 };
    if (q_dump_count.load() < 3) {
        const int qc = q_dump_count.fetch_add(1);
        // bug#2 (2026-07-18): also dump the CSA attention CONSUMPTION tensors (pinned in build_csa_lid_attention
        // at nt==1) for the offline decode-attention-math oracle - the last un-verified suspect.
        // Decode-only names (see build_csa_lid_attention). The old list asked for "csa_lid_kq_mask-2"
        // and "attn_csa_lid-2", which are the PREFILL-graph names: the mask one resolved to a tensor
        // that was never pinned, so its buffer had been recycled and the dump was meaningless.
        for (const char * qn : { "lid_q_rot-2", "qr_norm-2", "lid_weights-2",
                                 "csa_dec_q-2", "csa_dec_k-2", "csa_dec_mask-2",
                                 "csa_dec_mask_pre-2", "csa_dec_out-2",
                                 "kq_soft_max-2" }) {  // the ACTUAL post-softmax decode attention weights
            ggml_tensor * qt = ggml_graph_get_tensor(gf, qn);
            if (!qt || !qt->buffer) { continue; }
            if (sched) {
                ggml_backend_t bk = ggml_backend_sched_get_tensor_backend(sched, qt);
                if (bk) { ggml_backend_synchronize(bk); }
            }
            const size_t nbytes = ggml_nbytes(qt);
            std::vector<uint8_t> raw(nbytes);
            ggml_backend_tensor_get(qt, raw.data(), 0, nbytes);
            char fname[1024];
            snprintf(fname, sizeof(fname), "%s.%s.s%d.bin", path, qn, qc);
            if (FILE * fb = std::fopen(fname, "wb")) {
                fwrite(raw.data(), 1, nbytes, fb);
                std::fclose(fb);
            }
            char mname[1024];
            snprintf(mname, sizeof(mname), "%s.qmanifest.tsv", path);
            if (FILE * fm = std::fopen(mname, "ab+")) {
                fprintf(fm, "%s\t%d\t%s\t%lld\t%lld\t%lld\t%zu\t%zu\t%zu\t%d\n",
                        qn, qc, ggml_type_name(qt->type),
                        (long long) qt->ne[0], (long long) qt->ne[1], (long long) qt->ne[2],
                        (size_t) qt->nb[0], (size_t) qt->nb[1], (size_t) qt->nb[2], (int) pos);
                std::fclose(fm);
            }
        }
    }

    for (int il = 0; il < n_layer; ++il) {
        const std::string topk_name  = "lid_top_k-" + std::to_string(il);
        const std::string score_name = "lid_score_masked-" + std::to_string(il);
        ggml_tensor * topk_t  = ggml_graph_get_tensor(gf, topk_name.c_str());
        ggml_tensor * score_t = ggml_graph_get_tensor(gf, score_name.c_str());
        if (!topk_t || !score_t || topk_t->type != GGML_TYPE_I32 || score_t->type != GGML_TYPE_F32 ||
                topk_t->ne[0] <= 0 || score_t->ne[0] <= 0 || !topk_t->buffer || !score_t->buffer) {
            continue;
        }
        if (sched) {
            ggml_backend_t bk = ggml_backend_sched_get_tensor_backend(sched, topk_t);
            if (bk) { ggml_backend_synchronize(bk); }
        }
        const size_t k     = (size_t) topk_t->ne[0];
        const size_t n_lid = (size_t) score_t->ne[0];
        std::vector<int32_t> rows(k);
        {
            const size_t span = (k - 1) * topk_t->nb[0] + sizeof(int32_t);
            std::vector<uint8_t> raw(span);
            ggml_backend_tensor_get(topk_t, raw.data(), 0, span);
            for (size_t i = 0; i < k; ++i) {
                std::memcpy(&rows[i], raw.data() + i * topk_t->nb[0], sizeof(int32_t));
            }
        }
        std::vector<float> scores(n_lid);
        {
            const size_t span = (n_lid - 1) * score_t->nb[0] + sizeof(float);
            std::vector<uint8_t> raw(span);
            ggml_backend_tensor_get(score_t, raw.data(), 0, span);
            for (size_t i = 0; i < n_lid; ++i) {
                std::memcpy(&scores[i], raw.data() + i * score_t->nb[0], sizeof(float));
            }
        }
        size_t n_finite = 0;
        for (float & v : scores) {
            if (std::isnan(v) || std::isinf(v)) { v = -std::numeric_limits<float>::infinity(); }
            else { n_finite++; }
        }
        std::vector<float> sorted(scores);
        const size_t kth_idx = std::min(k, sorted.size()) - 1;
        std::nth_element(sorted.begin(), sorted.begin() + kth_idx, sorted.end(), std::greater<float>());
        const float kth_score  = sorted[kth_idx];
        const float top1_score = *std::max_element(scores.begin(), scores.end());
        size_t consistent = 0;
        for (int32_t r : rows) {
            if (r >= 0 && (size_t) r < scores.size() && scores[(size_t) r] >= kth_score) {
                consistent++;
            }
        }
        float needle_score = std::numeric_limits<float>::quiet_NaN();
        int   needle_rank  = -1;
        if (needle_row >= 0 && (size_t) needle_row < scores.size()) {
            needle_score = scores[(size_t) needle_row];
            needle_rank  = 0;
            for (float v : scores) {
                if (v > needle_score) { needle_rank++; }
            }
        }
        std::fprintf(fp, "%d\t%d\t%d\t%zu\t%d\t%zu\tresident\t", step, (int) pos, il, n_lid, -1, k);
        for (size_t i = 0; i < rows.size(); ++i) {
            if (i != 0) { std::fputc(',', fp); }
            std::fprintf(fp, "%d", rows[i]);
        }
        std::fprintf(fp, "\t%.4f\t%.6f\t%.6f\t%d\t%.6f\t%zu\n",
                k ? (double) consistent / (double) k : 0.0,
                (double) kth_score, (double) needle_score, needle_rank,
                (double) top1_score, n_finite);
    }
    std::fclose(fp);
}

llama_context::llama_context(const llama_model & model, llama_context_params params) :
    model(model),
    balloc(std::make_unique<llama_batch_allocr>(model.hparams.n_pos_per_embd())) {
    // TODO warning when creating llama_context with awkward ctx size that is not a power of 2,
    //     may need to be backend-dependent
    LLAMA_LOG_INFO("%s: constructing llama_context\n", __func__);

    t_start_us = model.t_start_us;
    t_load_us  = model.t_load_us;

    const auto & hparams = model.hparams;

    cparams.n_seq_max = std::max(1u, params.n_seq_max);
    if (cparams.n_seq_max > LLAMA_MAX_SEQ) {
        throw std::runtime_error("n_seq_max must be <= " + std::to_string(LLAMA_MAX_SEQ));
    }

    cparams.n_threads        = params.n_threads;
    cparams.n_threads_batch  = params.n_threads_batch;
    cparams.yarn_ext_factor  = params.yarn_ext_factor >= 0.0f ? params.yarn_ext_factor : hparams.yarn_ext_factor;
    cparams.yarn_attn_factor = params.yarn_attn_factor >= 0.0f ? params.yarn_attn_factor : hparams.yarn_attn_factor;
    cparams.yarn_beta_fast   = params.yarn_beta_fast >= 0.0f ? params.yarn_beta_fast : hparams.yarn_beta_fast;
    cparams.yarn_beta_slow   = params.yarn_beta_slow >= 0.0f ? params.yarn_beta_slow : hparams.yarn_beta_slow;
    cparams.embeddings       = params.embeddings;
    cparams.offload_kqv      = params.offload_kqv;
    cparams.offload_recurrent = params.offload_kqv;
    cparams.no_perf          = params.no_perf;
    cparams.pooling_type     = params.pooling_type;
    cparams.warmup           = false;

    cparams.n_ctx           = params.n_ctx == 0 ? hparams.n_ctx_train : params.n_ctx;
    cparams.rope_freq_base  = params.rope_freq_base == 0.0f ? hparams.rope_freq_base_train : params.rope_freq_base;
    cparams.rope_freq_scale = params.rope_freq_scale == 0.0f ? hparams.rope_freq_scale_train : params.rope_freq_scale;

    cparams.n_ctx_orig_yarn = params.yarn_orig_ctx != 0    ? params.yarn_orig_ctx :
                              hparams.n_ctx_orig_yarn != 0 ? hparams.n_ctx_orig_yarn :
                                                             hparams.n_ctx_train;

    cparams.cb_eval           = params.cb_eval;
    cparams.cb_eval_user_data = params.cb_eval_user_data;

    // STEP 2: install the layer-compare dump hook through the path-independent cb_eval if the
    // env is set and the caller did not provide its own cb_eval. Fires on the RTX streaming path
    // and the Mac receiver re-prefill alike (same lib) -> RTX-vs-Mac FA-precision confirmation.
    if (!cparams.cb_eval) {
        const char * e = std::getenv("LLAMA_LAYER_CMP_DUMP");
        if (e && e[0] && e[0] != '0') {
            cparams.cb_eval           = llama_layer_cmp_eval_cb;
            cparams.cb_eval_user_data = nullptr;
            LLAMA_LOG_INFO("%s: LAYER_CMP dump hook installed via cb_eval (SIDE=%s)\n",
                           __func__, std::getenv("LLAMA_LAYER_CMP_SIDE") ? std::getenv("LLAMA_LAYER_CMP_SIDE") : "x");
        }
    }

    const char * resident_lid_trace = std::getenv("LLAMA_DSV4_LID_TOPK_TRACE");
    if (model.arch == LLM_ARCH_DEEPSEEK4 && resident_lid_trace && resident_lid_trace[0] != '\0') {
        resident_lid_trace_enabled   = true;
        resident_lid_trace_path      = resident_lid_trace;
        resident_lid_trace_user_cb   = cparams.cb_eval;
        resident_lid_trace_user_data = cparams.cb_eval_user_data;
        if (const char * needle = std::getenv("LLAMA_DSV4_LID_NEEDLE_ROW")) {
            resident_lid_trace_needle_row = std::atoi(needle);
        }
        cparams.cb_eval           = resident_lid_eval_callback;
        cparams.cb_eval_user_data = this;
        LLAMA_LOG_INFO("%s: RESIDENT_LID_TRACE enabled path='%s' needle_row=%d\n",
                __func__, resident_lid_trace_path.c_str(), resident_lid_trace_needle_row);
    }

    // RTX streaming prefill mode
    prefill_streaming     = params.prefill_streaming;
    prefill_only          = params.prefill_only;
    prefill_overlap       = params.prefill_overlap;
    prefill_kv_type_k     = params.type_k;
    prefill_kv_type_v     = params.type_v;
    prefill_kv_swa_full   = params.swa_full;
    prefill_min_stream_batch_tokens = params.prefill_min_stream_batch_tokens;
    prefill_layer_buffers = params.prefill_layer_buffers;
    prefill_prefetch_distance = params.prefill_prefetch_distance;
    prefill_slab_bytes        = params.prefill_slab_bytes;
    prefill_host_cache_window_layers = params.prefill_host_cache_window_layers;
    prefill_host_cache_window_bytes  = params.prefill_host_cache_window_bytes;
    prefill_host_cache_prefetch_distance = std::max<int32_t>(1, params.prefill_host_cache_prefetch_distance);
    prefill_decode_mode       = params.prefill_decode_mode;
    prefill_decode_gpu_layers = params.prefill_decode_gpu_layers;
    prefill_decode_remote_layers = params.prefill_decode_remote_layers;
    prefill_decode_strict_partition = params.prefill_decode_strict_partition;
    prefill_decode_require_no_fallback = params.prefill_decode_require_no_fallback;
    prefill_decode_transport_required = params.prefill_decode_transport_required;
    prefill_decode_remote_nodes = std::max<int32_t>(1, params.prefill_decode_remote_nodes);
    prefill_decode_remote_ranges = params.prefill_decode_remote_ranges ? params.prefill_decode_remote_ranges : "";
    prefill_decode_remote_failover = params.prefill_decode_remote_failover ? params.prefill_decode_remote_failover : "reroute";
    if (prefill_decode_remote_failover.empty()) {
        prefill_decode_remote_failover = "reroute";
    }
    prefill_transport_mode      = params.prefill_transport_mode;
    prefill_execution_mode      = params.prefill_execution_mode;
    prefill_tb_chunk_bytes      = std::max<int32_t>(1, params.prefill_tb_chunk_bytes);
    prefill_kv_transport      = params.prefill_kv_transport ? params.prefill_kv_transport : "";
    prefill_tb_direct_endpoint = params.prefill_tb_direct_endpoint ? params.prefill_tb_direct_endpoint : "";
    prefill_kv_host           = params.prefill_kv_host ? params.prefill_kv_host : "";
    prefill_kv_port           = params.prefill_kv_port;
    prefill_kv_streams        = params.prefill_kv_streams;
    prefill_kv_stream_chunk_bytes = params.prefill_kv_stream_chunk_bytes;
    prefill_kv_max_inflight_bytes = params.prefill_kv_max_inflight_bytes;
    prefill_kv_socket_send_buf = params.prefill_kv_socket_send_buf;
    prefill_kv_socket_recv_buf = params.prefill_kv_socket_recv_buf;
    prefill_kv_bind_addrs     = params.prefill_kv_bind_addrs ? params.prefill_kv_bind_addrs : "";
    prefill_kv_peer_addrs     = params.prefill_kv_peer_addrs ? params.prefill_kv_peer_addrs : "";
    prefill_kv_balance        = params.prefill_kv_balance ? params.prefill_kv_balance : "";
    prefill_kv_transport_fallback = params.prefill_kv_transport_fallback;
    prefill_loopback_remote_gpu = params.prefill_loopback_remote_gpu;
    prefill_kv_validate_import  = params.prefill_kv_validate_import;
    prefill_remote_weights      = params.prefill_remote_weights;
    prefill_remote_weights_hybrid = params.prefill_remote_weights_hybrid;
    prefill_shadow_catchup = params.prefill_shadow_catchup;
    prefill_shadow_catchup_threshold_tokens = params.prefill_shadow_catchup_threshold_tokens;
    prefill_shadow_catchup_max_batch = params.prefill_shadow_catchup_max_batch;
    prefill_kv_artifact_path = params.prefill_kv_artifact_path ? params.prefill_kv_artifact_path : "";
    prefill_tb_session_dir   = params.prefill_tb_session_dir ? params.prefill_tb_session_dir : "";
    prefill_strategy         = params.prefill_strategy;
    prefill_crossover_tokens = params.prefill_crossover_tokens;
    token_stream_host        = params.token_stream_host ? params.token_stream_host : "";
    token_stream_port        = params.token_stream_port;
    kv_sync_batch_size       = params.kv_sync_batch_size;

    cparams.sparse_mla = resolve_tristate_flag(params.sparse_mla, "LLAMA_MLA_SPARSE", false);
    cparams.sparse_mla_trace = resolve_tristate_flag(params.sparse_mla_trace, "LLAMA_MLA_SPARSE_TRACE", false);
    cparams.sparse_mla_prefill = resolve_tristate_flag(params.sparse_mla_prefill, "LLAMA_MLA_SPARSE_PREFILL", true);
    cparams.sparse_mla_decode = resolve_tristate_flag(params.sparse_mla_decode, "LLAMA_MLA_SPARSE_DECODE", true);
    cparams.sparse_mla_top_k = resolve_int_override(params.sparse_mla_top_k, "LLAMA_MLA_SPARSE_TOP_K", 0);
    cparams.sparse_mla_prefill_top_k =
        resolve_int_override(params.sparse_mla_prefill_top_k, "LLAMA_MLA_SPARSE_PREFILL_TOP_K", 0);
    cparams.sparse_mla_prefill_selector = resolve_sparse_mla_selector(
        params.sparse_mla_prefill_selector,
        "LLAMA_MLA_SPARSE_PREFILL_RECENT",
        "LLAMA_MLA_SPARSE_PREFILL_PREFIX",
        LLAMA_SPARSE_MLA_SELECTOR_SCORE);
    cparams.sparse_mla_prefill_indexer = params.sparse_mla_prefill_indexer >= 0 ?
        params.sparse_mla_prefill_indexer != 0 :
        !env_truthy_value(std::getenv("LLAMA_MLA_SPARSE_PREFILL_SKIP_INDEXER"));
    cparams.sparse_mla_decode_baseline = resolve_sparse_mla_selector(
        params.sparse_mla_decode_baseline,
        "LLAMA_MLA_SPARSE_RECENT",
        "LLAMA_MLA_SPARSE_PREFIX",
        LLAMA_SPARSE_MLA_SELECTOR_SCORE);
    cparams.sparse_mla_fa_mode = resolve_sparse_mla_fa_mode(params.sparse_mla_fa_mode);
    cparams.sparse_mla_fused_kernel =
        resolve_tristate_flag(params.sparse_mla_fused_kernel, "LLAMA_MLA_SPARSE_FUSED_KERNEL", false);
    cparams.sparse_mla_fused_topk =
        resolve_tristate_flag(params.sparse_mla_fused_topk, "LLAMA_MLA_SPARSE_FUSED_TOPK", false);
    cparams.moe_prefill_expert_cap =
        resolve_int_override(params.moe_prefill_expert_cap, "LLAMA_MOE_PREFILL_EXPERT_CAP", 0);
    cparams.mtp_mode = sanitize_mtp_mode(params.mtp_mode, LLAMA_MTP_MODE_OFF);
    cparams.mtp_max_draft = sanitize_mtp_max_draft(params.mtp_max_draft);

    LLAMA_LOG_INFO("%s: sparse MLA = %s (prefill=%s, decode=%s, fa_mode=%d, prefill_selector=%d, decode_baseline=%d, fused=%s/%s)\n",
                   __func__,
                   cparams.sparse_mla ? "enabled" : "disabled",
                   cparams.sparse_mla_prefill ? "on" : "off",
                   cparams.sparse_mla_decode ? "on" : "off",
                   cparams.sparse_mla_fa_mode,
                   cparams.sparse_mla_prefill_selector,
                   cparams.sparse_mla_decode_baseline,
                   cparams.sparse_mla_fused_kernel ? "score" : "off",
                   cparams.sparse_mla_fused_topk ? "topk" : "off");
    if (llama_mtp_mode_enabled(cparams.mtp_mode)) {
        LLAMA_LOG_INFO("%s: native NextN/MTP mode = %d (max draft=%d)\n",
                       __func__, cparams.mtp_mode, cparams.mtp_max_draft);
    }

    bool prefill_streaming_min_batch_from_env = false;
    bool prefill_streaming_min_batch_from_auto = false;
    bool prefill_streaming_min_batch_from_cli = params.prefill_min_stream_batch_tokens > 0;
    if (prefill_min_stream_batch_tokens <= 0) {
        const char * env_value = std::getenv("GGML_OP_OFFLOAD_MIN_BATCH");
        if (env_value != nullptr && env_value[0] != '\0') {
            char * end = nullptr;
            long parsed = std::strtol(env_value, &end, 10);
            if (end != env_value && *end == '\0' && parsed >= 1 && parsed <= std::numeric_limits<int32_t>::max()) {
                prefill_min_stream_batch_tokens = static_cast<int32_t>(parsed);
                prefill_streaming_min_batch_from_env = true;
            } else {
                LLAMA_LOG_WARN("%s: invalid GGML_OP_OFFLOAD_MIN_BATCH='%s'; using default streaming threshold (32)\n",
                               __func__, env_value);
            }
        }
    }
    if (prefill_min_stream_batch_tokens <= 0 &&
        decode_uses_remote_split_engine(prefill_decode_mode, prefill_decode_remote_layers, prefill_decode_remote_nodes, prefill_decode_remote_ranges)) {
        double stream_floor_ms = 4000.0;
        double stream_tok_s    = 2500.0;
        double decode_tok_s    = 220.0;

        (void) parse_env_double("LLAMA_PREFILL_STREAM_FLOOR_MS", stream_floor_ms);
        (void) parse_env_double("LLAMA_PREFILL_STREAM_TOK_S", stream_tok_s);
        (void) parse_env_double("LLAMA_PREFILL_DECODE_TOK_S", decode_tok_s);

        prefill_min_stream_batch_tokens =
            compute_stream_crossover_tokens(stream_floor_ms, stream_tok_s, decode_tok_s, /*fallback_min_tokens=*/32);
        prefill_streaming_min_batch_from_auto = true;

        LLAMA_LOG_INFO(
            "%s: prefill crossover auto-threshold=%d (stream_floor_ms=%.3f, stream_tok_s=%.3f, decode_tok_s=%.3f)\n",
            __func__, prefill_min_stream_batch_tokens, stream_floor_ms, stream_tok_s, decode_tok_s);
    }
    if (prefill_min_stream_batch_tokens <= 0) {
        prefill_min_stream_batch_tokens = 32;
    }

    LLAMA_LOG_INFO("%s: prefill decode mode = %s (gpu_layers=%d, remote_layers=%d, remote_nodes=%d, remote_ranges=%s, remote_failover=%s, strict_partition=%s, require_no_fallback=%s, transport_required=%s, transport_mode=%d, exec_mode=%d)\n", __func__,
                   llama_prefill_decode_mode_name(prefill_decode_mode), prefill_decode_gpu_layers,
                   prefill_decode_remote_layers, prefill_decode_remote_nodes,
                   prefill_decode_remote_ranges.empty() ? "<none>" : prefill_decode_remote_ranges.c_str(),
                   prefill_decode_remote_failover.c_str(),
                   prefill_decode_strict_partition ? "true" : "false",
                   prefill_decode_require_no_fallback ? "true" : "false",
                   prefill_decode_transport_required ? "true" : "false", prefill_transport_mode, prefill_execution_mode);
    LLAMA_LOG_INFO("%s: prefill streaming min batch = %d tokens (source: %s)\n",
                   __func__, prefill_min_stream_batch_tokens,
                   prefill_streaming_min_batch_from_cli
                       ? "cli/api override"
                       : (prefill_streaming_min_batch_from_env
                              ? "GGML_OP_OFFLOAD_MIN_BATCH"
                              : (prefill_streaming_min_batch_from_auto ? "auto crossover (ik decode engine)" : "default")));
    if (!prefill_kv_transport.empty() || !prefill_tb_direct_endpoint.empty() ||
        !prefill_kv_host.empty() || prefill_kv_port > 0 || prefill_kv_streams > 0) {
        LLAMA_LOG_INFO("%s: prefill transport overrides: kv_transport=%s, endpoint=%s, kv_host=%s, kv_port=%d, kv_streams=%d, fallback=%s, loopback_remote_gpu=%s\n",
                       __func__,
                       prefill_kv_transport.empty() ? "<env/default>" : prefill_kv_transport.c_str(),
                       prefill_tb_direct_endpoint.empty() ? "<env/default>" : prefill_tb_direct_endpoint.c_str(),
                       prefill_kv_host.empty() ? "<env/default>" : prefill_kv_host.c_str(),
                       prefill_kv_port, prefill_kv_streams,
                       prefill_kv_transport_fallback ? "on" : "off",
                       prefill_loopback_remote_gpu ? "on" : "off");
    }
    if (prefill_shadow_catchup) {
        const int32_t default_threshold = std::max<int32_t>(1, static_cast<int32_t>(cparams.n_ubatch) / 2);
        const int32_t default_max_batch = std::max<int32_t>(1, static_cast<int32_t>(cparams.n_ubatch));
        const int32_t effective_max_batch = prefill_shadow_catchup_max_batch > 0 ? prefill_shadow_catchup_max_batch : default_max_batch;
        const int32_t requested_threshold =
            prefill_shadow_catchup_threshold_tokens > 0 ? prefill_shadow_catchup_threshold_tokens : default_threshold;
        const int32_t effective_threshold = std::min(requested_threshold, effective_max_batch);
        if (requested_threshold > effective_max_batch) {
            LLAMA_LOG_WARN("%s: shadow catch-up threshold (%d) exceeds max batch (%d); clamping to %d\n",
                           __func__, requested_threshold, effective_max_batch, effective_threshold);
        }
        LLAMA_LOG_INFO("%s: shadow catch-up enabled (threshold=%d, max_batch=%d)\n",
                       __func__, effective_threshold, effective_max_batch);
    }
    if (prefill_host_cache_window_layers > 0 || prefill_host_cache_window_bytes > 0) {
        LLAMA_LOG_INFO("%s: S3 host moving-window enabled (layers=%d, bytes=%d, prefetch_distance=%d)\n",
                       __func__, prefill_host_cache_window_layers, prefill_host_cache_window_bytes,
                       prefill_host_cache_prefetch_distance);
    }

    // Initialize backend samplers here so they are part of the sampling graph
    // before the reserve passes run later in this function. This avoids a later
    // re-reserve when graph nodes change.
    if (params.samplers != nullptr && params.n_samplers > 0) {
        for (size_t i = 0; i < params.n_samplers; ++i) {
            const auto & config = params.samplers[i];

            if (llama_sampler_chain_get(config.sampler, -1) == nullptr) {
                throw std::runtime_error("the backend samplers must be of type llama_sampler_chain");
            }

            if (set_sampler(config.seq_id, config.sampler)) {
                const int n_samplers = llama_sampler_chain_n(config.sampler);

                LLAMA_LOG_INFO("%s: setting backend sampler for seq_id %d (n = %d)\n", __func__, config.seq_id,
                               n_samplers);
            }
        }
    }

    auto rope_scaling_type = params.rope_scaling_type;
    if (rope_scaling_type == LLAMA_ROPE_SCALING_TYPE_UNSPECIFIED) {
        rope_scaling_type = hparams.rope_scaling_type_train;
    }

    if (rope_scaling_type == LLAMA_ROPE_SCALING_TYPE_NONE) {
        cparams.rope_freq_scale = 1.0f;  // never scale if scaling type is none
    }

    if (cparams.yarn_ext_factor < 0.0f) {  // negative indicates 'not set'
        cparams.yarn_ext_factor = rope_scaling_type == LLAMA_ROPE_SCALING_TYPE_YARN ? 1.0f : 0.0f;
    }

    if (cparams.yarn_ext_factor != 0) {
        static auto get_mscale = [](float scale, float mscale) {
            return scale <= 1.0f ? 1.0f : (0.1f * mscale * logf(scale) + 1.0f);
        };

        const float factor = 1.0f / cparams.rope_freq_scale;

        // ref: https://github.com/huggingface/transformers/blob/6d00f6b0a5679c36510f203e4226e36f517c3032/src/transformers/modeling_rope_utils.py#L336-L348
        if (hparams.rope_yarn_log_mul != 0.0f) {
            // note: here we assume `mscale == 1.0f`
            // TODO: start reading the actual value of mscale and handle the case where it is not 1.0f
            float       mscale          = 1.0f;
            const float mscale_all_dims = hparams.rope_yarn_log_mul;

            // [TAG_DEEPSEEK2_YARN_LOG_MUL_FIX]
            // special-case DEEPSEEK v2:
            // https://huggingface.co/deepseek-ai/DeepSeek-V2-Lite-Chat/blob/main/config.json#L42-L43
            if ((model.arch == LLM_ARCH_DEEPSEEK2 || model.arch == LLM_ARCH_GLM_DSA) && mscale_all_dims != 1.0f) {
                mscale = mscale_all_dims;
            }

            cparams.yarn_attn_factor = get_mscale(factor, mscale) / get_mscale(factor, mscale_all_dims);

            LLAMA_LOG_WARN("%s: setting new yarn_attn_factor = %.4f (mscale == %.1f, mscale_all_dim = %.1f)\n",
                           __func__, cparams.yarn_attn_factor, mscale, mscale_all_dims);
        } else {
            cparams.yarn_attn_factor = get_mscale(factor, 1.0f);
        }

        // when YARN is applied with yarn_ext_factor != 0.0f, we need to cancel this factor:
        // https://github.com/ggml-org/llama.cpp/blob/a81a569577cc38b32558958b048228150be63eae/ggml/src/ggml-cpu/ops.cpp#L5541-L5544
        //
        // ref: https://github.com/ggml-org/llama.cpp/discussions/7416
        //      https://github.com/ggml-org/llama.cpp/pull/17945
        cparams.yarn_attn_factor *= 1.0f / (1.0f + 0.1f * logf(factor));
    }

    cparams.yarn_attn_factor *= hparams.rope_attn_factor;

    if (cparams.pooling_type == LLAMA_POOLING_TYPE_UNSPECIFIED) {
        if (hparams.pooling_type == LLAMA_POOLING_TYPE_UNSPECIFIED) {
            cparams.pooling_type = LLAMA_POOLING_TYPE_NONE;
        } else {
            cparams.pooling_type = hparams.pooling_type;
        }
    }

    if (params.attention_type == LLAMA_ATTENTION_TYPE_UNSPECIFIED) {
        cparams.causal_attn = hparams.causal_attn;
    } else {
        cparams.causal_attn = params.attention_type == LLAMA_ATTENTION_TYPE_CAUSAL;
    }

    cparams.flash_attn = params.flash_attn_type != LLAMA_FLASH_ATTN_TYPE_DISABLED;
    cparams.auto_fa    = params.flash_attn_type == LLAMA_FLASH_ATTN_TYPE_AUTO;
    prefill_kv_layout_flash_attn = cparams.flash_attn;
    // with causal attention, the batch size is limited by the context size
    cparams.n_batch = cparams.causal_attn ? std::min(cparams.n_ctx, params.n_batch) : params.n_batch;

    // FA + MLA: align n_batch DOWN to 256 (FATTN_KQ_STRIDE).
    // The CUDA FA kernel requires n_kv % 256 == 0 for dkq=576 (MLA).
    // Aligning DOWN splits the prompt: first batch = aligned FA, remainder = non-streaming.
    if (cparams.flash_attn && model.hparams.is_mla() && cparams.n_batch > 256) {
        uint32_t aligned = cparams.n_batch & ~255u;
        if (aligned != cparams.n_batch && aligned >= 256) {
            LLAMA_LOG_INFO("%s: FA+MLA: aligning n_batch %u -> %u (remainder → next batch)\n",
                    __func__, cparams.n_batch, aligned);
            cparams.n_batch = aligned;
        }
    }

    cparams.n_ubatch = std::min(cparams.n_batch, params.n_ubatch == 0 ? params.n_batch : params.n_ubatch);

    // FA requires 256-token alignment on both n_batch and n_ubatch for correct
    // attention tile strides on MLA models (Kimi/GLM/DeepSeek). The previous
    // 64-token alignment was correct for non-MLA but produced silent KV
    // corruption in the [880, 1500]-token tail band on MLA models. 256 is the
    // safe global value (per llama-prefill-stream.cpp:fa_tail_align for MLA)
    // and supersets the 64-token requirement of non-MLA. Round DOWN (never
    // up — prompts can exceed and carry a Mac-handled tail).
    if (cparams.flash_attn) {
        constexpr uint32_t fa_align = 256;
        if (cparams.n_batch > fa_align) {
            uint32_t aligned = cparams.n_batch & ~(fa_align - 1);
            if (aligned != cparams.n_batch) {
                LLAMA_LOG_WARN("%s: FA: aligning n_batch %u -> %u (256-token multiple)\n",
                        __func__, cparams.n_batch, aligned);
                cparams.n_batch = aligned;
            }
        }
        if (cparams.n_ubatch > fa_align) {
            uint32_t aligned = cparams.n_ubatch & ~(fa_align - 1);
            if (aligned != cparams.n_ubatch) {
                LLAMA_LOG_WARN("%s: FA: aligning n_ubatch %u -> %u (256-token multiple)\n",
                        __func__, cparams.n_ubatch, aligned);
                cparams.n_ubatch = aligned;
            }
        }
        if (cparams.n_ubatch > cparams.n_batch) {
            cparams.n_ubatch = cparams.n_batch;
        }
    }

    cparams.op_offload = params.op_offload;
    cparams.kv_unified = params.kv_unified;

    // intialized later
    cparams.pipeline_parallel = false;

    // MoE expert split (env-controlled for WF sub-layer pipelining)
    {
        const char * splits_env = std::getenv("LLAMA_WF_LAYER_SPLITS");
        cparams.n_expert_splits = (splits_env && splits_env[0]) ? std::atoi(splits_env) : 1;
        if (cparams.n_expert_splits < 1) cparams.n_expert_splits = 1;
        if (cparams.n_expert_splits > 8) cparams.n_expert_splits = 8;
    }

    {
        const char * LLAMA_GRAPH_REUSE_DISABLE = getenv("LLAMA_GRAPH_REUSE_DISABLE");
        graph_reuse_disable = LLAMA_GRAPH_REUSE_DISABLE ? (atoi(LLAMA_GRAPH_REUSE_DISABLE) != 0) : graph_reuse_disable;

        if (graph_reuse_disable) {
            LLAMA_LOG_WARN("%s: graph reuse disabled\n", __func__);
        }
    }

    // ref: https://github.com/ggml-org/llama.cpp/pull/17046#discussion_r2503085732
    cparams.n_ctx = GGML_PAD(cparams.n_ctx, 256);

    if (cparams.kv_unified) {
        cparams.n_ctx_seq = cparams.n_ctx;
    } else {
        cparams.n_ctx_seq = cparams.n_ctx / cparams.n_seq_max;
        cparams.n_ctx_seq = GGML_PAD(cparams.n_ctx_seq, 256);

        if (cparams.n_ctx_seq == 0) {
            throw std::runtime_error("n_ctx_seq == 0");
        }

        if (cparams.n_ctx != cparams.n_ctx_seq * cparams.n_seq_max) {
            cparams.n_ctx = cparams.n_ctx_seq * cparams.n_seq_max;
            LLAMA_LOG_WARN("%s: n_ctx is not divisible by n_seq_max - rounding down to %u\n", __func__, cparams.n_ctx);
        }
    }

    LLAMA_LOG_INFO("%s: n_seq_max     = %u\n", __func__, cparams.n_seq_max);
    LLAMA_LOG_INFO("%s: n_ctx         = %u\n", __func__, cparams.n_ctx);
    LLAMA_LOG_INFO("%s: n_ctx_seq     = %u\n", __func__, cparams.n_ctx_seq);
    LLAMA_LOG_INFO("%s: n_batch       = %u\n", __func__, cparams.n_batch);
    LLAMA_LOG_INFO("%s: n_ubatch      = %u\n", __func__, cparams.n_ubatch);
    LLAMA_LOG_INFO("%s: causal_attn   = %d\n", __func__, cparams.causal_attn);
    LLAMA_LOG_INFO("%s: flash_attn    = %s\n", __func__, llama_flash_attn_type_name(params.flash_attn_type));
    LLAMA_LOG_INFO("%s: kv_unified    = %s\n", __func__, cparams.kv_unified ? "true" : "false");
    LLAMA_LOG_INFO("%s: freq_base     = %.1f\n", __func__, cparams.rope_freq_base);
    LLAMA_LOG_INFO("%s: freq_scale    = %g\n", __func__, cparams.rope_freq_scale);

    if (cparams.n_ctx_seq < hparams.n_ctx_train) {
        LLAMA_LOG_WARN("%s: n_ctx_seq (%u) < n_ctx_train (%u) -- the full capacity of the model will not be utilized\n",
                       __func__, cparams.n_ctx_seq, hparams.n_ctx_train);
    }

    if (cparams.n_ctx_seq > hparams.n_ctx_train) {
        LLAMA_LOG_WARN("%s: n_ctx_seq (%u) > n_ctx_train (%u) -- possible training context overflow\n", __func__,
                       cparams.n_ctx_seq, hparams.n_ctx_train);
    }

    if (!hparams.vocab_only) {
        // GPU backends
        for (auto * dev : model.devices) {
            ggml_backend_t backend = ggml_backend_dev_init(dev, nullptr);
            if (backend == nullptr) {
                throw std::runtime_error(format("failed to initialize %s backend", ggml_backend_dev_name(dev)));
            }
            backends.emplace_back(backend);
        }

        // add ACCEL backends (such as BLAS)
        for (size_t i = 0; i < ggml_backend_dev_count(); ++i) {
            ggml_backend_dev_t dev = ggml_backend_dev_get(i);
            if (ggml_backend_dev_type(dev) == GGML_BACKEND_DEVICE_TYPE_ACCEL) {
                ggml_backend_t backend = ggml_backend_dev_init(dev, nullptr);
                if (backend == nullptr) {
                    throw std::runtime_error(format("failed to initialize %s backend", ggml_backend_dev_name(dev)));
                }
                backends.emplace_back(backend);
            }
        }

        // add CPU backend
        backend_cpu = ggml_backend_init_by_type(GGML_BACKEND_DEVICE_TYPE_CPU, nullptr);
        if (backend_cpu == nullptr) {
            throw std::runtime_error("failed to initialize CPU backend");
        }
        backends.emplace_back(backend_cpu);

        // create a list of the set_n_threads functions in the backends
        for (auto & backend : backends) {
            ggml_backend_dev_t dev = ggml_backend_get_device(backend.get());
            ggml_backend_reg_t reg = dev ? ggml_backend_dev_backend_reg(dev) : nullptr;
            if (reg) {
                auto ggml_backend_set_n_threads_fn =
                    (ggml_backend_set_n_threads_t) ggml_backend_reg_get_proc_address(reg, "ggml_backend_set_n_threads");
                if (ggml_backend_set_n_threads_fn) {
                    set_n_threads_fns.emplace_back(backend.get(), ggml_backend_set_n_threads_fn);
                }
            }
        }

        llama_set_abort_callback(this, params.abort_callback, params.abort_callback_data);

        // graph outputs buffer
        {
            if (output_reserve(params.n_seq_max) < params.n_seq_max) {
                throw std::runtime_error("failed to reserve initial output buffer");
            }

            LLAMA_LOG_INFO("%s: %10s  output buffer size = %8.2f MiB\n", __func__,
                           ggml_backend_buffer_name(buf_output.get()),
                           ggml_backend_buffer_get_size(buf_output.get()) / 1024.0 / 1024.0);
        }
    }

    // init the memory module
    if (!hparams.vocab_only) {
        // In streaming prefill mode, KV cache and recurrent state MUST be on GPU
        // so that all compute stays on the accelerator during the layer-by-layer
        // weight streaming pass.
        LLAMA_LOG_DEBUG("%s: offload_kqv=%d prefill_streaming=%d n_gpu_layers=%u\n",
            __func__, cparams.offload_kqv, prefill_streaming, model.n_gpu_layers());
        // KV-RAM mode: keep KV cache on CPU at init to avoid VRAM blowup.
        // decode_layer_major creates a small GPU staging buffer as needed.
        // Without this, c=32768+ OOMs because the full KV is allocated on GPU
        // at init and only freed later.
        const auto kv_cfg = llama_prefill_resolve_kv_mode_from_env();
        const bool dsv4_aux_offload = [&]() {
            if (!prefill_streaming || kv_cfg.mode != LLAMA_KV_RAM) {
                return false;
            }

            for (auto * dev : model.devices) {
                if (dev && ggml_backend_dev_type(dev) == GGML_BACKEND_DEVICE_TYPE_GPU) {
                    return true;
                }
            }

            for (size_t i = 0; i < ggml_backend_dev_count(); ++i) {
                auto * dev = ggml_backend_dev_get(i);
                if (dev && ggml_backend_dev_type(dev) == GGML_BACKEND_DEVICE_TYPE_GPU) {
                    return true;
                }
            }

            return false;
        }();
        fprintf(stderr, "*** KV_INIT: prefill_streaming=%d kv_mode=%s forced=%d source=%s value=%s\n",
                (int) prefill_streaming,
                kv_cfg.mode == LLAMA_KV_RAM ? "ram" : "gpu",
                (int) kv_cfg.forced,
                kv_cfg.source,
                kv_cfg.value ? kv_cfg.value : "NULL");
        fflush(stderr);
        if (kv_cfg.explicit_env && !kv_cfg.recognized) {
            fprintf(stderr, "*** KV_INIT: unrecognized %s=%s, defaulting to gpu\n",
                    kv_cfg.source, kv_cfg.value ? kv_cfg.value : "NULL");
            fflush(stderr);
        }
        if (prefill_streaming && kv_cfg.mode == LLAMA_KV_GPU) {
            cparams.offload_kqv = true;
            cparams.offload_recurrent = true;
            fprintf(stderr, "*** KV_INIT: forced offload_kqv=true (KV on GPU)\n"); fflush(stderr);
        } else if (prefill_streaming && kv_cfg.mode == LLAMA_KV_RAM) {
            cparams.offload_kqv = false;
            cparams.offload_recurrent = true;
            fprintf(stderr, "*** KV_INIT: KV-RAM mode — KV cache on CPU (saves VRAM for large contexts)\n"); fflush(stderr);
        }

        llama_memory_params params_mem = {
            /*.type_k            =*/params.type_k,
            /*.type_v            =*/params.type_v,
            /*.swa_full          =*/params.swa_full,
            /*.dsv4_aux_offload  =*/dsv4_aux_offload,
        };

        memory.reset(model.create_memory(params_mem, cparams));
    }

    // init backends
    if (!hparams.vocab_only) {
        LLAMA_LOG_DEBUG("%s: enumerating backends\n", __func__);

        backend_buft.clear();
        backend_ptrs.clear();
        backend_buf_exp_size.clear();

        for (auto & backend : backends) {
            auto * buft         = ggml_backend_get_default_buffer_type(backend.get());
            auto   backend_type = ggml_backend_dev_type(ggml_backend_get_device(backend.get()));

            if (backend_type == GGML_BACKEND_DEVICE_TYPE_CPU && !model.devices.empty() && prefill_streaming) {
                // Use CUDA_Host (pinned) for context buffers (KV cache,
                // compute scratch) ONLY when streaming prefill is active.
                // Pinned memory is required for streaming-prefill CUDA kernels
                // to access CPU-side buffers via DMA.
                // Without --prefill-streaming, use default (unpinned) CPU buffers
                // to avoid large pinned RAM allocations during normal decode.
                auto * dev       = model.devices[0];
                auto * host_buft = ggml_backend_dev_host_buffer_type(dev);
                if (host_buft) {
                    buft = host_buft;
                    LLAMA_LOG_DEBUG("%s: using CUDA_Host pinned buffers for streaming prefill\n", __func__);
                }
            }

            backend_buft.push_back(buft);
            backend_ptrs.push_back(backend.get());
            backend_buf_exp_size.push_back(0);
        }

        LLAMA_LOG_DEBUG("%s: backend_ptrs.size() = %zu\n", __func__, backend_ptrs.size());

        // TODO: move these checks to ggml_backend_sched
        // enabling pipeline parallelism in the scheduler increases memory usage, so it is only done when necessary
        bool pipeline_parallel = model.n_devices() > 1 && model.n_gpu_layers() > model.hparams.n_layer &&
                                 model.split_mode() == LLAMA_SPLIT_MODE_LAYER && cparams.offload_kqv &&
                                 !model.has_tensor_overrides();

        // pipeline parallelism requires support for async compute and events in all devices
        if (pipeline_parallel) {
            for (auto & backend : backends) {
                auto dev_type = ggml_backend_dev_type(ggml_backend_get_device(backend.get()));
                if (dev_type == GGML_BACKEND_DEVICE_TYPE_CPU) {
                    // ignore CPU backend
                    // TODO: should we ignore ACCEL types too?
                    continue;
                }
                auto *                 dev = ggml_backend_get_device(backend.get());
                ggml_backend_dev_props props;
                ggml_backend_dev_get_props(dev, &props);
                if (!props.caps.async || !props.caps.events) {
                    // device does not support async compute or events
                    pipeline_parallel = false;
                    break;
                }
            }
        }

        cparams.pipeline_parallel = pipeline_parallel;

        if (cparams.pipeline_parallel) {
            LLAMA_LOG_INFO("%s: pipeline parallelism enabled\n", __func__);
        }

        sched_reserve();

        if (!cparams.flash_attn) {
            if (ggml_is_quantized(params.type_v)) {
                throw std::runtime_error("quantized V cache was requested, but this requires Flash Attention");
            }
        }
    }

    // Initialize the full vocabulary token ids for backend samplers.
    {
        const int n_vocab = model.vocab.n_tokens();

        sampling.token_ids_full_vocab.resize(n_vocab);
        for (int i = 0; i < n_vocab; ++i) {
            sampling.token_ids_full_vocab[i] = i;
        }
    }
}

llama_context::~llama_context() {
    // Free split-decode cached staging buffers.
    if (split_in_buf)   { ggml_backend_buffer_free(split_in_buf);   split_in_buf = nullptr; }
    if (split_attn_buf) { ggml_backend_buffer_free(split_attn_buf); split_attn_buf = nullptr; }

    // L1 dense-residency working set: restore nothing (process is tearing down), just free VRAM.
    if (dense_resident_buf) { ggml_backend_buffer_free(dense_resident_buf); dense_resident_buf = nullptr; }

    // L2 expert slab + LRU arena + cached file handles.
    if (expert_slab_buf) { ggml_backend_buffer_free(expert_slab_buf); expert_slab_buf = nullptr; }
    if (expert_lru_buf)  { ggml_backend_buffer_free(expert_lru_buf);  expert_lru_buf  = nullptr; }
    for (auto & kv : expert_slab_files) { if (kv.second) fclose(kv.second); }
    expert_slab_files.clear();

    if (!model.hparams.no_alloc && !model.hparams.wf_active) {
        for (size_t i = 0; i < backend_ptrs.size(); ++i) {
            ggml_backend_t             backend = backend_ptrs[i];
            ggml_backend_buffer_type_t buft    = backend_buft[i];

            const size_t size_exp = backend_buf_exp_size[i];
            const size_t size_act = ggml_backend_sched_get_buffer_size(sched.get(), backend);
            if (size_exp == size_act) {
                LLAMA_LOG_DEBUG("%s: %10s compute buffer size is %8.4f MiB, matches expectation of %8.4f MiB\n",
                                __func__, ggml_backend_buft_name(buft), size_act / (1024.0 * 1024.0),
                                size_exp / (1024.0 * 1024.0));
            } else {
                LLAMA_LOG_WARN("%s: %10s compute buffer size of %8.4f MiB, does not match expectation of %8.4f MiB\n",
                               __func__, ggml_backend_buft_name(buft), size_act / (1024.0 * 1024.0),
                               size_exp / (1024.0 * 1024.0));
            }
        }
    }
    // Destroy cached weight fetcher if still alive
    if (cached_wf) {
        wf_destroy((wf_context *)cached_wf);
        cached_wf = nullptr;
    }

    ggml_opt_free(opt_ctx);
}

// L2 expert-slab routed-fetch callback (defined near ensure_expert_slab_for_decode)
static bool llama_expert_slab_eval_cb(ggml_tensor * t, bool ask, void * user_data);

void llama_context::sched_reserve() {
    if (!sched_need_reserve) {
        return;
    }

    sched_need_reserve = false;

    LLAMA_LOG_INFO("%s: reserving ...\n", __func__);

    synchronize();

    const int64_t t_start_us = ggml_time_us();

    const uint32_t n_seqs   = cparams.n_seq_max;
    // For streaming prefill: reserve with minimal tokens so WDDM virtual
    // memory commits are small, leaving room for WF GPU buffers.
    // decode_layer_major rebuilds and alloc's the graph at actual batch size.
    // NOTE (2026-05-30): LLAMA_PREFILL_RESERVE_FULL (up-front reserve) was tried for
    // the 100k OOM and REFUTED — it enlarges the (still-live) init reserve and makes
    // OOM worse. The 100k OOM is a CONTIGUOUS-alloc fragmentation issue (the n_kv-scaled
    // prefill compute buffer can't find a contiguous slot among the WF buf + graph),
    // not a deferral issue. Real fix = shrink the compute buffer (direct_causal kernel,
    // eliminate the kq_mask leaf) or reorder allocation. See §11 long-ctx design.
    const uint32_t n_tokens = (model.hparams.wf_active && prefill_streaming)
                            ? 1 : std::min(cparams.n_ctx, cparams.n_ubatch);

    const size_t max_nodes = this->graph_max_nodes(n_tokens);

    LLAMA_LOG_DEBUG("%s: max_nodes = %zu\n", __func__, max_nodes);

    gf_res_prev.reset(new llm_graph_result(max_nodes));
    gf_res_reserve.reset(new llm_graph_result(max_nodes));

    sched.reset(ggml_backend_sched_new(backend_ptrs.data(), backend_buft.data(), backend_ptrs.size(), max_nodes,
                                       cparams.pipeline_parallel, cparams.op_offload));
    if (expert_slab_buf) {
        LLAMA_LOG_INFO("sched_reserve: EXPERT_SLAB eval-callback re-installed on the new sched\n");
        // L2 expert slab: the routed-expert fetch callback must survive sched recreation —
        // the FIRST slab build sets sched_need_reserve, and without this re-install the very
        // next (batch/prompt) graph computed on the fresh sched ran UNOBSERVED, leaving the
        // slab unwritten -> garbage prompt KV (verified 2026-07-20: prompt eval fired no
        // callbacks, decode ids degenerated to 0..5 from layer 3).
        ggml_backend_sched_set_eval_callback(sched.get(), llama_expert_slab_eval_cb, this);
    }

    llama_memory_context_ptr mctx;
    if (memory) {
        mctx = memory->init_full();
        if (!mctx) {
            throw std::runtime_error("failed to initialize memory module");
        }
    }

    // avoid reserving graphs with zero outputs - assume one output per sequence
    const int n_outputs = n_seqs;

    LLAMA_LOG_DEBUG("%s: worst-case: n_tokens = %d, n_seqs = %d, n_outputs = %d\n", __func__, n_tokens, n_seqs,
                    n_outputs);

    // resolve automatic Flash Attention use
    if (cparams.auto_fa) {
        auto * gf = graph_reserve(1, n_seqs, n_outputs, mctx.get(), true);
        if (!gf) {
            throw std::runtime_error("failed to split graph for Flash Attention check");
        }

        const size_t prefix_len         = strlen(LLAMA_TENSOR_NAME_FATTN) + 1;
        bool         fa_device_mismatch = false;

        ggml_backend_dev_t streaming_prefill_device = nullptr;
        if (prefill_streaming && model.n_gpu_layers() == 0) {
            for (const auto & backend : backends) {
                auto * dev = ggml_backend_get_device(backend.get());
                if (dev && ggml_backend_dev_type(dev) != GGML_BACKEND_DEVICE_TYPE_CPU) {
                    streaming_prefill_device = dev;
                    break;
                }
            }
        }
        for (int i = 0; i < ggml_graph_n_nodes(gf); i++) {
            ggml_tensor * n = ggml_graph_node(gf, i);
            if (n->op != GGML_OP_FLASH_ATTN_EXT) {
                continue;
            }
            ggml_backend_dev_t device_fa =
                ggml_backend_get_device(ggml_backend_sched_get_tensor_backend(sched.get(), n));

            // TODO: instead of the tensor names, use a map to keep track of which (FA) tensors belong to which layer
            GGML_ASSERT(strncmp(n->name, LLAMA_TENSOR_NAME_FATTN "-", prefix_len) == 0);
            const int          il        = std::stoi(n->name + prefix_len);
            ggml_backend_dev_t device_expected = model.dev_layer(il);
            if (streaming_prefill_device) {
                // In streaming prefill, weights are uploaded dynamically and layer compute
                // is intentionally pushed to GPU even when static model residency is CPU.
                // Validate Flash Attention placement against the streaming execution device.
                device_expected = streaming_prefill_device;
            }
            if (device_fa != device_expected) {
                LLAMA_LOG_WARN(
                    "%s: layer %d is assigned to device %s but the Flash Attention tensor "
                    "is assigned to device %s (usually due to missing support)\n",
                    __func__, il, ggml_backend_dev_name(device_expected), ggml_backend_dev_name(device_fa));
                // FIXME: fa_device_mismatch logic is wrong for --no-kv-offload, but this is broken anyways
                fa_device_mismatch = true;
                break;
            }
        }
        if (fa_device_mismatch) {
            cparams.flash_attn = false;
            LLAMA_LOG_WARN("%s: Flash Attention was auto, set to disabled\n", __func__);
        } else {
            cparams.flash_attn = true;
            LLAMA_LOG_INFO("%s: Flash Attention was auto, set to enabled\n", __func__);
        }

        cparams.auto_fa = false;
    }

    // reserve worst-case graph
    int n_splits_pp = -1;
    int n_nodes_pp  = -1;

    int n_splits_tg = -1;
    int n_nodes_tg  = -1;

    const bool skip_alloc = model.hparams.no_alloc || model.hparams.wf_active;

    // reserve pp (prompt processing) graph first so that buffers are only allocated once
    {
        auto * gf = graph_reserve(n_tokens, n_seqs, n_tokens, mctx.get(), skip_alloc,
                                  skip_alloc ? backend_buf_exp_size.data() : nullptr);
        if (!gf) {
            if (cparams.pipeline_parallel) {
                LLAMA_LOG_WARN("%s: compute buffer allocation failed, retrying without pipeline parallelism\n",
                               __func__);
                cparams.pipeline_parallel = false;
                sched.reset(ggml_backend_sched_new(backend_ptrs.data(), backend_buft.data(), backend_ptrs.size(),
                                                   max_nodes, false, cparams.op_offload));
                if (expert_slab_buf) {
                    ggml_backend_sched_set_eval_callback(sched.get(), llama_expert_slab_eval_cb, this);
                }
                gf = graph_reserve(n_tokens, n_seqs, n_tokens, mctx.get());
            }
            if (!gf) {
                throw std::runtime_error("failed to allocate compute pp buffers");
            }
        }

        n_splits_pp = ggml_backend_sched_get_n_splits(sched.get());
        n_nodes_pp  = ggml_graph_n_nodes(gf);
    }

    // reserve with tg (token generation) graph to get the number of splits and nodes
    {
        auto * gf = graph_reserve(n_seqs, n_seqs, n_seqs, mctx.get(), skip_alloc);
        if (!gf) {
            throw std::runtime_error("failed to allocate compute tg buffers");
        }

        n_splits_tg = ggml_backend_sched_get_n_splits(sched.get());
        n_nodes_tg  = ggml_graph_n_nodes(gf);
    }

    // reserve again with pp graph to avoid ggml-alloc reallocations during inference
    {
        // TODO: not sure if the following graph would be worster case for multi-stream KV caches:
        //
        // auto * gf = graph_reserve(n_tokens, 1, n_tokens, mctx.get());
        //
        auto * gf = graph_reserve(n_tokens, n_seqs, n_tokens, mctx.get(), skip_alloc);
        if (!gf) {
            throw std::runtime_error("failed to allocate compute pp buffers");
        }
    }

    for (size_t i = 0; i < backend_ptrs.size(); ++i) {
        ggml_backend_t             backend = backend_ptrs[i];
        ggml_backend_buffer_type_t buft    = backend_buft[i];
        if (!skip_alloc) {
            backend_buf_exp_size[i] = ggml_backend_sched_get_buffer_size(sched.get(), backend);
        }
        if (backend_buf_exp_size[i] > 1) {
            LLAMA_LOG_INFO("%s: %10s compute buffer size = %8.2f MiB\n", __func__, ggml_backend_buft_name(buft),
                           backend_buf_exp_size[i] / 1024.0 / 1024.0);
        }
    }

    if (n_nodes_pp == n_nodes_tg) {
        LLAMA_LOG_INFO("%s: graph nodes  = %d\n", __func__, n_nodes_pp);
    } else {
        LLAMA_LOG_INFO("%s: graph nodes  = %d (with bs=%d), %d (with bs=1)\n", __func__, n_nodes_pp, n_tokens,
                       n_nodes_tg);
    }

    if (n_splits_pp == n_splits_tg) {
        LLAMA_LOG_INFO("%s: graph splits = %d\n", __func__, n_splits_pp);
    } else {
        LLAMA_LOG_INFO("%s: graph splits = %d (with bs=%d), %d (with bs=1)\n", __func__, n_splits_pp, n_tokens,
                       n_splits_tg);
    }

    const int64_t t_end_us = ggml_time_us();

    LLAMA_LOG_INFO("%s: reserve took %.2f ms, sched copies = %d\n", __func__, (t_end_us - t_start_us) / 1000.0,
                   ggml_backend_sched_get_n_copies(sched.get()));
}

void llama_context::synchronize() {
    if (!sched) {
        return;
    }

    ggml_backend_sched_synchronize(sched.get());

    // FIXME: if multiple single tokens are evaluated without a synchronization,
    // the stats will be added to the prompt evaluation stats
    // this should only happen when using batch size 1 to evaluate a batch

    // add the evaluation to the stats
    if (n_queued_tokens == 1) {
        if (!cparams.no_perf) {
            t_eval_us += ggml_time_us() - t_compute_start_us;
        }
        n_eval++;
    } else if (n_queued_tokens > 1) {
        if (!cparams.no_perf) {
            t_p_eval_us += ggml_time_us() - t_compute_start_us;
        }
        n_p_eval += n_queued_tokens;
    }

    // get a more accurate load time, upon first eval
    if (n_queued_tokens > 0 && !has_evaluated_once) {
        t_load_us          = ggml_time_us() - t_start_us;
        has_evaluated_once = true;
    }

    n_queued_tokens    = 0;
    t_compute_start_us = 0;
}

