// Phase G (2026-05-06): MLA-aware KV capture for KVBlob v2 handoff.
// Mirrors capture_kv_state_blob's MLA setup at llama-context.cpp:2792.
// Without setting v_trans on the attn caches before state_seq access,
// the cell layout is incompatible with the legacy state_seq writer and
// state_seq_get_size_ext crashes on MLA models like DeepSeek-V2 / Kimi.
size_t llama_handoff_capture_kv(llama_context * ctx,
                                llama_seq_id    seq_id,
                                uint8_t *       dst,
                                size_t          size) {
    if (!ctx) return 0;
    ctx->synchronize();

    // MLA setup: flip attn caches to the legacy export layout so
    // state_seq_write_data can walk them.
    std::vector<llama_kv_cache *> export_caches;
    std::vector<bool> prev_v_trans;
    auto * mem = ctx->get_memory();
    const bool is_mla = ctx->get_model().hparams.is_mla();
    if (is_mla && mem) {
        export_caches = llama_memory_get_attn_caches_for_export(mem);
        prev_v_trans.reserve(export_caches.size());
        for (auto * cache : export_caches) {
            prev_v_trans.push_back(cache->get_v_trans());
            cache->set_v_trans(true);
        }
    }

    size_t result = 0;
    try {
        if (dst == nullptr || size == 0) {
            // Sizing query.
            result = ctx->state_seq_get_size(seq_id, 0);
        } else {
            result = ctx->state_seq_get_data(seq_id, dst, size, 0);
        }
    } catch (const std::exception & e) {
        LLAMA_LOG_ERROR("%s: error capturing kv for seq %d: %s\n",
                        __func__, seq_id, e.what());
        result = 0;
    }

    // Restore v_trans on each cache.
    if (is_mla) {
        for (size_t i = 0; i < export_caches.size(); ++i) {
            export_caches[i]->set_v_trans(prev_v_trans[i]);
        }
    }
    return result;
}

size_t llama_state_seq_save_file(llama_context *     ctx,
                                 const char *        filepath,
                                 llama_seq_id        seq_id,
                                 const llama_token * tokens,
                                 size_t              n_token_count) {
    ctx->synchronize();

    try {
        return ctx->state_seq_save_file(seq_id, filepath, tokens, n_token_count);
    } catch (const std::exception & err) {
        LLAMA_LOG_ERROR("%s: error saving sequence state file: %s\n", __func__, err.what());
        return 0;
    }
}

size_t llama_state_seq_load_file(llama_context * ctx,
                                 const char *    filepath,
                                 llama_seq_id    dest_seq_id,
                                 llama_token *   tokens_out,
                                 size_t          n_token_capacity,
                                 size_t *        n_token_count_out) {
    ctx->synchronize();

    try {
        return ctx->state_seq_load_file(dest_seq_id, filepath, tokens_out, n_token_capacity, n_token_count_out);
    } catch (const std::exception & err) {
        LLAMA_LOG_ERROR("%s: error loading sequence state file: %s\n", __func__, err.what());
        return 0;
    }
}

///

int32_t llama_encode(llama_context * ctx, llama_batch batch) {
    const int ret = ctx->encode(batch);
    if (ret != 0) {
        LLAMA_LOG_ERROR("%s: failed to encode, ret = %d\n", __func__, ret);
    }

    return ret;
}

int32_t llama_decode(llama_context * ctx, llama_batch batch) {
    // When weight fetcher is active (no_alloc), layer weights have sentinel data.
    // Only streaming prefill can work (WF loads weights on-the-fly).  If the batch
    // is too small for streaming, we cannot decode — skip gracefully.
    // EXCEPTION: the inner llama_decode() call from decode_streaming() must always
    // proceed through ctx->decode() — weights are loaded by the WF callbacks.
    const bool wf_active = ctx->get_model().hparams.wf_active;
    const char * keep_mmap_env = std::getenv("LLAMA_WF_KEEP_MMAP");
    // bug#2 routing experiment (env LLAMA_DSV4_WF_DECODE=1, default OFF): the retrieval FAILURE is that the
    // resident post-prefill decode (nt==1) and the ragged question-suffix use ordinary ctx->decode with the
    // DSV4 state MIGRATED TO CPU - a different backend forward than the retrieval-building streamed WF
    // prefill (sol-downstream top lead 0.74). When set, DON'T classify as resident_post_prefill / resident
    // prompt-tail, so both fall through to decode_streaming(batch) = the WF GPU path with no CPU migration.
    static const bool wf_decode_env = []() {
        const char * e = std::getenv("LLAMA_DSV4_WF_DECODE");
        return e && e[0] != '\0' && e[0] != '0';
    }();
    // GOAL#1 executor-selection fix (2026-07-20, env LLAMA_STREAM_LOCAL_RESIDENT_DECODE, default ON;
    // set =0 to restore the old dispatch): in STREAM_LOCAL mode should_use_streaming_for_batch()
    // returns true for EVERY batch, and resident_post_prefill additionally required
    // is_wf_prefill_done(). For prompts <256 tokens the FA-aligned streamed prefix is empty, so
    // wf_prefill_done stays FALSE and the FIRST generated token (n_tokens==1) was classified
    // ACTION_STREAMING_PREFILL -> decode_streaming() re-streamed the ENTIRE model (99 GB for
    // DSV4-flash; measured 145 s cold / 18-25 s warm) to produce ONE token — and that per-request
    // whole-model DirectStorage pass also evicted the OS cache the resident decode depends on.
    // Every stream_local decode token must instead dispatch the RESIDENT executor (ordinary
    // ctx->decode() on the keep_mmap weight view) — the same executor tokens 2+ already use.
    // DSV4-first: bypass restricted to LLM_ARCH_DEEPSEEK4. split_thunderbolt is untouched
    // (mode check). keep_mmap=0 (pure re-streaming decode) is untouched.
    static const bool stream_local_resident_decode_env = []() {
        const char * e = std::getenv("LLAMA_STREAM_LOCAL_RESIDENT_DECODE");
        return !(e && e[0] != '\0' && e[0] == '0');
    }();
    const bool resident_decode_ready =
            ctx->is_wf_prefill_done() ||
            (stream_local_resident_decode_env &&
             ctx->get_model().arch == LLM_ARCH_DEEPSEEK4 &&
             !ctx->is_inside_streaming_decode());
    // L1: with a VRAM-resident dense working set (LLAMA_WF_DECODE_RESIDENT_MB) the resident
    // decode no longer needs the mmap weight view — allow keep_mmap=0 (the no-thrash config).
    static const bool dense_resident_env = []() {
        const char * e = std::getenv("LLAMA_WF_DECODE_RESIDENT_MB");
        return e && e[0] != '\0' && std::atoi(e) > 0;
    }();
    const bool keep_mmap_set =
            keep_mmap_env && keep_mmap_env[0] != '\0' && std::strcmp(keep_mmap_env, "0") != 0;
    const bool resident_post_prefill =
            wf_active &&
            !wf_decode_env &&
            ctx->get_prefill_decode_mode() == LLAMA_PREFILL_DECODE_MODE_STREAM_LOCAL &&
            resident_decode_ready &&
            batch.n_tokens == 1 &&
            (keep_mmap_set || dense_resident_env);
    if (resident_post_prefill && !ctx->is_wf_prefill_done()) {
        static bool logged_once = false;
        if (!logged_once) {
            logged_once = true;
            LLAMA_LOG_INFO("%s: STREAM_LOCAL_RESIDENT_DECODE — dispatching resident executor for decode "
                           "token (wf_prefill_done=0 bypass; whole-model per-token re-stream suppressed)\n",
                           __func__);
        }
    }
    const bool wf_skip   = wf_active && !ctx->is_inside_streaming_decode() && !resident_post_prefill;
    const bool should_stream_batch = ctx->should_use_streaming_for_batch(batch);

    // After streaming prefill completes, layer weight tensors still point at
    // sentinel data.  Block non-streaming decode (generation) which would OOM
    // creating a second WF or crash on sentinel data.
    // BUT: allow additional prefill batches through — decode_streaming will
    // reuse the existing WF for the next pass through the layers.
    // After streaming prefill completes, weights are gone (sentinel data).
    // Decide whether to hand off to Mac or skip decode.
    llama_streaming_local_decode_inputs stream_local_inputs = {};
    stream_local_inputs.wf_active               = wf_active;
    stream_local_inputs.wf_prefill_done         = ctx->is_wf_prefill_done();
    stream_local_inputs.inside_streaming_decode = ctx->is_inside_streaming_decode();
    stream_local_inputs.should_stream_batch     = should_stream_batch;
    stream_local_inputs.handoff_pending         = ctx->has_decode_handoff_pending();
    stream_local_inputs.decode_mode             = ctx->get_prefill_decode_mode();
    stream_local_inputs.batch_tokens            = batch.n_tokens;
    stream_local_inputs.mtp_mode                = ctx->get_cparams().mtp_mode;
    stream_local_inputs.nextn_predict_layers    = (int32_t) ctx->get_model().hparams.nextn_predict_layers;
    stream_local_inputs.mtp_max_draft           = ctx->get_cparams().mtp_max_draft;
    const auto stream_local_decision = llama_streaming_local_decode_select(stream_local_inputs);

    if (stream_local_decision.clear_wf_prefill_done && !resident_post_prefill) {
        ctx->set_wf_prefill_done(false);
    }

    const bool run_streaming = !resident_post_prefill && (
        stream_local_decision.action == LLAMA_STREAMING_LOCAL_ACTION_STREAMING_PREFILL ||
        stream_local_decision.action == LLAMA_STREAMING_LOCAL_ACTION_STREAMING_LOCAL_DECODE);
    bool resident_prompt_tail = false;
    if (!wf_decode_env && run_streaming && keep_mmap_env && keep_mmap_env[0] != '\0' &&
            std::strcmp(keep_mmap_env, "0") != 0 && batch.n_tokens > 1) {
        if (batch.logits) {
            for (int32_t i = 0; i < batch.n_tokens; ++i) {
                resident_prompt_tail = resident_prompt_tail || batch.logits[i] != 0;
            }
        } else {
            resident_prompt_tail = true;
        }
    }

    bool crossover_streamed_prompt = false;
    // GOAL#1 quick win (env LLAMA_STREAM_LOCAL_PREFILL_CROSSOVER, default 0 = off; DSV4 +
    // STREAM_LOCAL only): prompts whose FA-aligned streamed prefix would be EMPTY (<256 tok)
    // used to evaluate ENTIRELY on the cold resident path (~0.7 GB/s page-fault rate; measured
    // 39 s TTFT for a 24-token prompt). When the prompt is longer than this crossover, route the
    // WHOLE prompt through the DirectStorage streaming prefill instead (17+ GB/s). Safe for the
    // ragged length: llama_prefill_stream keeps FA ON for unaligned DSV4 stream_local tails
    // (keep_dsv4_stream_local_fa, llama-prefill-stream.cpp:3106-3109), so the KV it writes stays
    // FA-on-compatible, and the bug#4 single-ubatch fast path is already excluded for
    // stream_local+keep_mmap. Decode tokens then dispatch the resident executor as usual.
    // Note: this bypasses the resident-tail RETAIN_SLOT_KV/migrate block — the prefill-written
    // KV simply stays GPU-resident (offload_kqv=true), which is the RETAIN semantics.
    if (resident_prompt_tail) {
        static const int32_t sl_prefill_crossover = []() {
            const char * e = std::getenv("LLAMA_STREAM_LOCAL_PREFILL_CROSSOVER");
            return e && e[0] != '\0' ? std::atoi(e) : 0;
        }();
        if (sl_prefill_crossover > 0 &&
                ctx->get_model().arch == LLM_ARCH_DEEPSEEK4 &&
                batch.n_tokens > sl_prefill_crossover) {
            static constexpr int32_t fa_align = 256;
            const int32_t last_index  = batch.n_tokens - 1;
            const int64_t last_pos    = batch.pos ? batch.pos[last_index] : last_index;
            const int64_t aligned_end = (last_pos / fa_align) * fa_align;
            const int64_t pos0        = batch.pos ? batch.pos[0] : 0;
            const int32_t prefix_tokens = (int32_t) std::max<int64_t>(0,
                    std::min<int64_t>(last_index, aligned_end - pos0));
            if (prefix_tokens == 0) {
                resident_prompt_tail = false;
                crossover_streamed_prompt = true;
                LLAMA_LOG_INFO("%s: STREAM_LOCAL_PREFILL_CROSSOVER — streaming whole %d-token prompt "
                               "(aligned prefix=0, crossover=%d; cold resident eval bypassed)\n",
                               __func__, batch.n_tokens, sl_prefill_crossover);
            }
        }
    }

    if (ctx->get_prefill_decode_mode() == LLAMA_PREFILL_DECODE_MODE_STREAM_LOCAL) {
        LLAMA_LOG_DEBUG("%s: stream_local select wf_active=%d wf_done=%d inside=%d should_stream=%d "
                "batch=%d action=%d reason=%s mtp=%s draft=%d target_graph=%d draft_graph=%d\n", __func__,
                wf_active ? 1 : 0,
                ctx->is_wf_prefill_done() ? 1 : 0,
                ctx->is_inside_streaming_decode() ? 1 : 0,
                should_stream_batch ? 1 : 0,
                batch.n_tokens,
                (int) stream_local_decision.action,
                stream_local_decision.reason ? stream_local_decision.reason : "(null)",
                stream_local_decision.mtp_plan.reason ? stream_local_decision.mtp_plan.reason : "(null)",
                stream_local_decision.mtp_plan.max_draft,
                stream_local_decision.mtp_plan.requires_target_graph ? 1 : 0,
                stream_local_decision.mtp_plan.requires_draft_graph ? 1 : 0);
    }

    if (stream_local_decision.action == LLAMA_STREAMING_LOCAL_ACTION_STREAMING_LOCAL_DECODE) {
        LLAMA_LOG_INFO("%s: wf prefill done - streaming local decode batch (n_tokens=%d)\n",
                       __func__, batch.n_tokens);
        if (stream_local_decision.mtp_plan.speculative) {
            LLAMA_LOG_INFO("%s: native MTP speculative plan active (max_draft=%d; target=base, draft=NextN)\n",
                           __func__, stream_local_decision.mtp_plan.max_draft);
        }
    } else if (stream_local_decision.action == LLAMA_STREAMING_LOCAL_ACTION_SKIP_DECODE) {
        LLAMA_LOG_WARN("%s: %s (n_tokens=%d)\n",
                       __func__, stream_local_decision.reason, batch.n_tokens);
        return 0;
    }

    bool handoff_bypass_wf_skip = stream_local_decision.bypass_wf_skip;
    if (wf_active && ctx->is_wf_prefill_done() && !ctx->is_inside_streaming_decode() && !resident_post_prefill) {
        if (!should_stream_batch) {
            if (ctx->has_decode_handoff_pending()) {
                // Decode handoff is armed — let decode() run so it calls
                // maybe_apply_decode_handoff() which exports KV and starts relay.
                LLAMA_LOG_INFO("%s: wf prefill done — entering decode() for handoff (n_tokens=%d)\n",
                               __func__, batch.n_tokens);
                handoff_bypass_wf_skip = true;
            } else {
                LLAMA_LOG_WARN("%s: wf prefill done — skipping post-prefill decode (n_tokens=%d, no handoff)\n",
                               __func__, batch.n_tokens);
                return 0;
            }
        } else {
            // Additional prefill batch — reset wf_prefill_done so decode_streaming
            // can create/reuse the WF for this pass.
            ctx->set_wf_prefill_done(false);
        }
    }

    // GOAL#1 L1: make the dense (non-routed-expert) weights VRAM-resident before the resident
    // token decode (no-op unless LLAMA_WF_DECODE_RESIDENT_MB is set; cheap re-point after the
    // first call). The resident prompt-tail case calls it AFTER its streamed prefix instead —
    // the prefix pass's wf_adapter_restore_tensors would undo a re-point done here.
    if (resident_post_prefill) {
        ctx->ensure_dense_resident_for_decode();
        // GOAL#1 L2: alias the *_exps tensors into the expert slab + arm the routed-expert
        // fetch callback (no-op unless LLAMA_WF_EXPERT_SLAB=1). Gives the keep_mmap=0
        // resident decode an expert byte source (kills the reserve assert on ffn_*_exps).
        ctx->ensure_expert_slab_for_decode();
        // TASK-A probe: aux/KV state stats right before the resident token decode reads them.
        // LLAMA_DSV4_AUX_DUMP_MAX (default 2) extends the process-lifetime token cap so
        // MULTI-REQUEST state diffs are possible (e.g. 70 captures request 2/3's first tokens
        // in a 32-tok-per-request bench); tokens beyond 2 get tag "pre-decode-tok<N>".
        static const int aux_dump_max = []() {
            const char * e = std::getenv("LLAMA_DSV4_AUX_DUMP_MAX");
            return (e && e[0] != '\0') ? atoi(e) : 2;
        }();
        static int aux_dump_tokens = 0;
        if (aux_dump_tokens < aux_dump_max) {
            ++aux_dump_tokens;
            char tagbuf[32];
            const char * tag = aux_dump_tokens == 1 ? "pre-decode-t1"
                             : aux_dump_tokens == 2 ? "pre-decode-t2" : tagbuf;
            if (aux_dump_tokens > 2) {
                snprintf(tagbuf, sizeof(tagbuf), "pre-decode-tok%d", aux_dump_tokens);
            }
            ctx->dsv4_aux_norm_dump(tag);
        }
    }

    int ret = 0;
    if (resident_prompt_tail) {
        // Keep the same correctness boundary as the proven RTX->Mac handoff:
        // stream only an FA-aligned prefix, then evaluate the complete ragged
        // suffix with the resident decoder. Streaming all but one token made
        // the DLM process an unaligned local-no-FA suffix whose compressed DSV4
        // state was finite but not semantically equivalent to resident decode.
        static constexpr int32_t fa_tail_align = 256;
        const int32_t output_index = batch.n_tokens - 1;
        const int64_t final_pos = batch.pos ? batch.pos[output_index] : output_index;
        const int64_t aligned_end = (final_pos / fa_tail_align) * fa_tail_align;
        const int64_t batch_pos0 = batch.pos ? batch.pos[0] : 0;
        const int32_t prefix_tokens = (int32_t) std::max<int64_t>(0,
                std::min<int64_t>(output_index, aligned_end - batch_pos0));

        ret = 0;
        if (prefix_tokens > 0) {
            llama_batch prefix = batch;
            prefix.n_tokens = prefix_tokens;
            std::vector<int8_t> prefix_logits((size_t) prefix_tokens, 0);
            prefix.logits = prefix_logits.data();
            ret = ctx->decode_streaming(prefix, ctx->get_prefill_layer_buffers());
        }
        if (ret == 0 && ctx->get_model().arch == LLM_ARCH_DEEPSEEK4) {
            // RETAIN-SLOT-KV (LLAMA_DSV4_RETAIN_SLOT_KV=1, default OFF): for the LOCAL
            // resident decode (stream_local mode = no Mac handoff) keep the GPU-resident
            // DSV4 module ALIVE instead of the migrate-to-CPU round trip. The resident
            // suffix/token decode then CONTINUES the prefill-written KV in place
            // (offload_kqv stays true -> GPU-FA attention), and the retained module
            // carries the conversation across turns: turn-N+1's pos0>0 continuation
            // self-skips both the new-prompt rebuild and the reverse-migrate (their
            // conditions require a CPU-backed module), so no O(context) serialize/
            // restore/re-prefill happens on the decode boundary or between turns.
            // The remote-relay retain path (maybe_apply_decode_handoff, crossover
            // handoff to Mac) is deliberately untouched by this gate.
            // NOTE (bug#2 dimension): this switches resident decode-token attention
            // from CPU to GPU-FA — the direction the migrate_kv_cache_to_cpu
            // diagnostic comment identifies as recall-helping. Re-run the needle/
            // recall harness when validating this gate.
            const bool retain_slot_kv =
                ctx->retain_slot_kv_enabled() &&
                ctx->get_prefill_decode_mode() == LLAMA_PREFILL_DECODE_MODE_STREAM_LOCAL;
            if (retain_slot_kv) {
                // Same race closure as the migrate blob path: drain the sched AND the
                // fork's non-blocking RAW compute/copy streams before the resident
                // decode reads the just-written KV cells.
                ctx->synchronize();
                ggml_backend_cuda_device_synchronize();
                {
                    static const bool dsv4_clear_trace = []() {
                        const char * e = std::getenv("LLAMA_DSV4_CLEAR_TRACE");
                        return e && e[0] != '\0' && e[0] != '0';
                    }();
                    if (dsv4_clear_trace) {
                        fprintf(stderr, "*** CLEAR_TRACE: retain-mark pos_max=%lld\n",
                                (long long) llama_memory_seq_pos_max(ctx->get_memory(), 0));
                    }
                }
                ctx->mark_kv_slot_resident();
                // TASK A: the layer-major pass D2H-downloaded every layer's cache (K/V/K_IDX)
                // into the KV-RAM host mirrors, leaving the GPU cells STALE — the resident
                // decode then attends garbage (streamed prompt INVISIBLE; ids degenerate to
                // 0..5 by layer 3). Re-upload the mirrors so the decode sees the streamed KV.
                // Opt-out: LLAMA_DSV4_KV_REUPLOAD=0.
                static const bool kv_reupload = []() {
                    const char * e = std::getenv("LLAMA_DSV4_KV_REUPLOAD");
                    return !e || e[0] == '\0' || e[0] != '0';
                }();
                if (kv_reupload) {
                    const size_t re_up = ctx->reupload_kv_ram_to_gpu();
                    if (re_up > 0) {
                        LLAMA_LOG_INFO("%s: RETAIN_SLOT_KV re-uploaded %.1f MiB streamed-KV mirrors to GPU\n",
                                       __func__, re_up / (1024.0 * 1024.0));
                    }
                }
                ctx->dsv4_aux_norm_dump("post-retain-tail");
                LLAMA_LOG_INFO("%s: RETAIN_SLOT_KV — DSV4 KV stays GPU-resident for stream_local decode "
                               "(no CPU migration; module epoch %llu)\n", __func__,
                               (unsigned long long) ctx->kv_module_epoch);
            } else if (!ctx->migrate_stream_local_kv_to_cpu()) {
                LLAMA_LOG_ERROR("%s: failed to migrate retained DSV4 state for resident stream_local decode\n", __func__);
                ret = -1;
            } else {
                // BUG#2 FIX (2026-07-16): the streamed prefix wrote K cells in the
                // FA-ON layout; reading them with the FA-off "conservative" graph is
                // NOT semantically equivalent for MLA (same mismatch the prefill
                // stream documents for the Mac decoder: FA-off produces numerically
                // different K). The old unconditional FA disable here scrambled every
                // resident suffix/decode read of prefill-written K — fluent output
                // (raw window rewritten locally) but no far-context retrieval. Keep
                // FA ON so the resident decoder reads the layout prefill wrote.
                // LLAMA_PREFILL_STREAM_LOCAL_FA_OFF=1 restores the old behavior for
                // A/B diagnosis only.
                const char * fa_off = std::getenv("LLAMA_PREFILL_STREAM_LOCAL_FA_OFF");
                if (fa_off && fa_off[0] != '\0' && fa_off[0] != '0') {
                    ctx->set_flash_attn_enabled(false);
                }
            }
        }
        if (ret == 0) {
            // GOAL#1 L1: dense weights to VRAM for the resident suffix eval (after the streamed
            // prefix — its restore_tensors put the layer tensors back on the mmap pointers).
            ctx->ensure_dense_resident_for_decode();
            // GOAL#1 L2: expert slab for the resident suffix eval (union fetch per layer).
            ctx->ensure_expert_slab_for_decode();
        }
        if (ret == 0) {
            llama_batch final = batch;
            final.n_tokens = batch.n_tokens - prefix_tokens;
            if (final.token) {
                final.token += prefix_tokens;
            }
            if (final.embd) {
                final.embd += (size_t) prefix_tokens * ctx->get_model().hparams.n_embd;
            }
            if (final.pos) {
                final.pos += prefix_tokens;
            }
            if (final.n_seq_id) {
                final.n_seq_id += prefix_tokens;
            }
            if (final.seq_id) {
                final.seq_id += prefix_tokens;
            }
            if (final.logits) {
                final.logits += prefix_tokens;
            }
            ret = ctx->decode(final);
            if (ret == 0) {
                ctx->remap_single_output(batch.n_tokens, output_index);

                // The migrate fingerprint's "post" phase is post-restore but still
                // pre-suffix.  Under the round-12 diagnostic, add an observation at
                // the actual post-suffix boundary so cache-row evidence is timed
                // against the execution it is intended to validate.
                const char * suffix_write_diag = std::getenv("LLAMA_DSV4_SUFFIX_WRITE_DIAG");
                const char * fingerprint_path = std::getenv("LLAMA_DSV4_MIGRATE_FINGERPRINT");
                if (suffix_write_diag && suffix_write_diag[0] != '\0' && suffix_write_diag[0] != '0' &&
                        fingerprint_path && fingerprint_path[0] != '\0') {
                    const auto * dsv4_memory = dynamic_cast<const llama_kv_cache_dsv4 *>(ctx->get_memory());
                    if (dsv4_memory) {
                        ctx->synchronize();
                        llama_dsv4_migrate_fingerprint_append(
                                fingerprint_path, "suffix-post", dsv4_memory);
                    }
                }
            }
        }
    } else if (run_streaming) {
        ret = ctx->decode_streaming(batch, ctx->get_prefill_layer_buffers());
        // CROSSOVER coherence boundary (round-2 fix): the ≥256 resident-tail flow ALWAYS closes
        // the streamed-write → resident-read race before any resident execution touches the
        // prefill-written KV — sync the sched AND the fork's non-blocking RAW compute/copy
        // streams, then either mark the GPU module slot-resident (RETAIN_SLOT_KV) or migrate to
        // the CPU module. The first crossover cut skipped this boundary and the resident decode
        // read incomplete KV: fluent but prompt-blind output ('<|endof|>' / "query appears to be
        // nonsensical", near-recall FALSE). Apply the identical boundary here.
        bool boundary_needed = crossover_streamed_prompt;
        if (!boundary_needed && dense_resident_env && !keep_mmap_set &&
                ctx->get_prefill_decode_mode() == LLAMA_PREFILL_DECODE_MODE_STREAM_LOCAL &&
                batch.n_tokens > 1 && batch.logits) {
            // keep_mmap=0 + L1: every logits-bearing prompt streams whole; close the same race
            // before the resident decode reads the streamed KV.
            for (int32_t i = 0; i < batch.n_tokens && !boundary_needed; ++i) {
                boundary_needed = batch.logits[i] != 0;
            }
        }
        if (ret == 0 && boundary_needed &&
                ctx->get_model().arch == LLM_ARCH_DEEPSEEK4) {
            const bool retain_slot_kv =
                ctx->retain_slot_kv_enabled() &&
                ctx->get_prefill_decode_mode() == LLAMA_PREFILL_DECODE_MODE_STREAM_LOCAL;
            if (retain_slot_kv) {
                ctx->synchronize();
                ggml_backend_cuda_device_synchronize();
                {
                    static const bool dsv4_clear_trace = []() {
                        const char * e = std::getenv("LLAMA_DSV4_CLEAR_TRACE");
                        return e && e[0] != '\0' && e[0] != '0';
                    }();
                    if (dsv4_clear_trace) {
                        fprintf(stderr, "*** CLEAR_TRACE: retain-mark pos_max=%lld\n",
                                (long long) llama_memory_seq_pos_max(ctx->get_memory(), 0));
                    }
                }
                ctx->mark_kv_slot_resident();
                // TASK A: same as the resident_prompt_tail retain site — the streamed pass
                // D2H'd every layer's cache into the KV-RAM mirrors and left the GPU cells
                // stale; re-upload so the resident decode SEES the streamed prompt.
                {
                    static const bool kv_reupload2 = []() {
                        const char * e = std::getenv("LLAMA_DSV4_KV_REUPLOAD");
                        return !e || e[0] == '\0' || e[0] != '0';
                    }();
                    if (kv_reupload2) {
                        const size_t re_up = ctx->reupload_kv_ram_to_gpu();
                        if (re_up > 0) {
                            LLAMA_LOG_INFO("%s: CROSSOVER+RETAIN_SLOT_KV re-uploaded %.1f MiB "
                                           "streamed-KV mirrors to GPU\n",
                                           __func__, re_up / (1024.0 * 1024.0));
                        }
                    }
                }
                ctx->dsv4_aux_norm_dump("post-retain-crossover");
                LLAMA_LOG_INFO("%s: CROSSOVER+RETAIN_SLOT_KV — streamed whole-prompt KV stays "
                               "GPU-resident for stream_local decode (race closed)\n", __func__);
            } else if (!ctx->migrate_stream_local_kv_to_cpu()) {
                LLAMA_LOG_ERROR("%s: CROSSOVER — failed to migrate streamed whole-prompt KV for "
                                "resident stream_local decode\n", __func__);
                ret = -1;
            }
        }
    } else if (wf_skip && !handoff_bypass_wf_skip) {
        ret = 0;
    } else {
        ret = ctx->decode(batch);
    }

    // decode_streaming returns 1 to signal "batch too small, use normal decode"
    if (ret == 1) {
        if (wf_skip) {
            // Phase 334 (2026-05-05): when wf_active and decode_streaming
            // returns 1 (e.g. init_batch FAILED_PREPARE under high NP), we
            // can't fall back to non-streaming decode (weights are sentinel).
            // Returning 0 here previously left output_ids unpopulated and
            // the sampler crashed reading null logits. Return -1 to signal
            // a real error so server's update_slots can re-queue or drop
            // the request gracefully.
            LLAMA_LOG_WARN("%s: wf_active — decode_streaming failed (ret=1) and non-streaming decode unavailable; returning error\n", __func__);
            ret = -1;
        } else {
            ret = ctx->decode(batch);
        }
    }

    // After streaming prefill with wf_active and transport configured, no logits
    // were computed (output head was skipped). Return 2 so the caller can trigger
    // the decode handoff outside the decode loop (blocking network I/O).
    // Only return 2 when transport is actually enabled — otherwise let normal
    // decode proceed (the wf_skip path handles non-streaming decode batches).
    if (ret == 0 && wf_active && ctx->is_wf_prefill_done() &&
        ctx->get_prefill_decode_mode() != LLAMA_PREFILL_DECODE_MODE_STREAM_LOCAL &&
        ctx->has_decode_handoff_pending() &&
        (ctx->get_prefill_transport_mode() != 0 || ctx->has_kv_artifact_path())) {
        fprintf(stderr, "*** HANDOFF: streaming prefill done, ret=2 (transport=%d artifact=%d)\n",
                ctx->get_prefill_transport_mode(), (int)ctx->has_kv_artifact_path());
        fflush(stderr);
        return 2;
    }

    if (ret != 0) {
        LLAMA_LOG_ERROR("%s: failed to decode, ret = %d\n", __func__, ret);
    }

    return ret;
}

bool llama_decode_trigger_handoff(llama_context * ctx) {
    if (!ctx) {
        return false;
    }
    return ctx->trigger_decode_handoff();
}

//
// perf
//

llama_perf_context_data llama_perf_context(const llama_context * ctx) {
    llama_perf_context_data data = {};

    if (ctx == nullptr) {
        return data;
    }

    data = ctx->perf_get_data();

    return data;
}

void llama_perf_context_print(const llama_context * ctx) {
    const auto data = llama_perf_context(ctx);

    const double t_end_ms = 1e-3 * ggml_time_us();

    LLAMA_LOG_INFO("%s:        load time = %10.2f ms\n", __func__, data.t_load_ms);
    LLAMA_LOG_INFO("%s: prompt eval time = %10.2f ms / %5d tokens (%8.2f ms per token, %8.2f tokens per second)\n",
                   __func__, data.t_p_eval_ms, data.n_p_eval, data.t_p_eval_ms / data.n_p_eval,
                   1e3 / data.t_p_eval_ms * data.n_p_eval);
    LLAMA_LOG_INFO("%s:        eval time = %10.2f ms / %5d runs   (%8.2f ms per token, %8.2f tokens per second)\n",
                   __func__, data.t_eval_ms, data.n_eval, data.t_eval_ms / data.n_eval,
                   1e3 / data.t_eval_ms * data.n_eval);
    LLAMA_LOG_INFO("%s:       total time = %10.2f ms / %5d tokens\n", __func__, (t_end_ms - data.t_start_ms),
                   (data.n_p_eval + data.n_eval));
    LLAMA_LOG_INFO("%s:    graphs reused = %10d\n", __func__, data.n_reused);
}

void llama_perf_context_reset(llama_context * ctx) {
    ctx->perf_reset();
}

void llama_memory_breakdown_print(const struct llama_context * ctx) {
    const std::vector<ggml_backend_dev_t> & devices = ctx->get_model().devices;

    std::map<ggml_backend_buffer_type_t, llama_memory_breakdown_data> memory_breakdown = ctx->memory_breakdown();

    std::vector<std::array<std::string, 9>> table_data;
    table_data.reserve(devices.size());
    const std::string template_header = "%s: | %s | %s   %s    %s   %s   %s   %s    %s |\n";
    const std::string template_gpu    = "%s: | %s | %s = %s + (%s = %s + %s + %s) + %s |\n";
    const std::string template_other  = "%s: | %s | %s   %s    %s = %s + %s + %s    %s |\n";

    table_data.push_back({ template_header, "memory breakdown [MiB]", "total", "free", "self", "model", "context",
                           "compute", "unaccounted" });

    constexpr size_t               MiB                 = 1024 * 1024;
    const std::vector<std::string> desc_prefixes_strip = { "NVIDIA ", "GeForce ", "Tesla ",
                                                           "AMD ",    "Radeon ",  "Instinct " };

    // track seen buffer types to avoid double counting:
    std::set<ggml_backend_buffer_type_t> seen_buffer_types;

    // accumulative memory breakdown for each device and for host:
    std::vector<llama_memory_breakdown_data> mb_dev(devices.size());
    llama_memory_breakdown_data              mb_host;

    for (const auto & buft_mb : memory_breakdown) {
        ggml_backend_buffer_type_t          buft = buft_mb.first;
        const llama_memory_breakdown_data & mb   = buft_mb.second;
        if (ggml_backend_buft_is_host(buft)) {
            mb_host.model += mb.model;
            mb_host.context += mb.context;
            mb_host.compute += mb.compute;
            seen_buffer_types.insert(buft);
            continue;
        }
        ggml_backend_dev_t dev = ggml_backend_buft_get_device(buft);
        if (dev) {
            int i_dev = -1;
            for (size_t i = 0; i < devices.size(); i++) {
                if (devices[i] == dev) {
                    i_dev = i;
                    break;
                }
            }
            if (i_dev != -1) {
                mb_dev[i_dev].model += mb.model;
                mb_dev[i_dev].context += mb.context;
                mb_dev[i_dev].compute += mb.compute;
                seen_buffer_types.insert(buft);
                continue;
            }
        }
    }

    // print memory breakdown for each device:
    for (size_t i = 0; i < devices.size(); i++) {
        ggml_backend_dev_t          dev = devices[i];
        llama_memory_breakdown_data mb  = mb_dev[i];

        const std::string name = ggml_backend_dev_name(dev);
        std::string       desc = ggml_backend_dev_description(dev);
        for (const std::string & prefix : desc_prefixes_strip) {
            if (desc.length() >= prefix.length() && desc.substr(0, prefix.length()) == prefix) {
                desc = desc.substr(prefix.length());
            }
        }

        size_t free, total;
        ggml_backend_dev_memory(dev, &free, &total);

        const size_t self        = mb.model + mb.context + mb.compute;
        const size_t unaccounted = total - self - free;

        table_data.push_back({ template_gpu, "  - " + name + " (" + desc + ")", std::to_string(total / MiB),
                               std::to_string(free / MiB), std::to_string(self / MiB), std::to_string(mb.model / MiB),
                               std::to_string(mb.context / MiB), std::to_string(mb.compute / MiB),
                               std::to_string(unaccounted / MiB) });
    }

    // print memory breakdown for host:
    {
        const size_t self = mb_host.model + mb_host.context + mb_host.compute;
        table_data.push_back({ template_other, "  - Host",
                               "",  // total
                               "",  // free
                               std::to_string(self / MiB), std::to_string(mb_host.model / MiB),
                               std::to_string(mb_host.context / MiB), std::to_string(mb_host.compute / MiB),
                               "" });  // unaccounted
    }

    // print memory breakdown for all remaining buffer types:
    for (const auto & buft_mb : memory_breakdown) {
        ggml_backend_buffer_type_t          buft = buft_mb.first;
        const llama_memory_breakdown_data & mb   = buft_mb.second;
        if (seen_buffer_types.count(buft) == 1) {
            continue;
        }
        const std::string name = ggml_backend_buft_name(buft);
        const size_t      self = mb.model + mb.context + mb.compute;
        table_data.push_back({ template_other, "  - " + name,
                               "",  // total
                               "",  // free
                               std::to_string(self / MiB), std::to_string(mb.model / MiB),
                               std::to_string(mb.context / MiB), std::to_string(mb.compute / MiB),
                               "" });  // unaccounted
        seen_buffer_types.insert(buft);
    }

    for (size_t j = 1; j < table_data[0].size(); j++) {
        size_t max_len = 0;
        for (const auto & td : table_data) {
            max_len = std::max(max_len, td[j].length());
        }
        for (auto & td : table_data) {
            td[j].insert(j == 1 ? td[j].length() : 0, max_len - td[j].length(), ' ');
        }
    }
    for (const auto & td : table_data) {
        LLAMA_LOG_INFO(td[0].c_str(), __func__, td[1].c_str(), td[2].c_str(), td[3].c_str(), td[4].c_str(),
                       td[5].c_str(), td[6].c_str(), td[7].c_str(), td[8].c_str());
    }
}

